type DashboardAuthPayload = {
  email?: unknown;

  phone?: unknown;

  name?: unknown;

  orgName?: unknown;

  role?: unknown;

  status?: unknown;

  expiresAt?: unknown;

  expiry?: unknown;
};

type DashboardAuthResult =
  | { authorized: true; identity: string; status: string; userId?: string }
  | { authorized: false };

function getDashboardLoginPath(role: Role) {
  if (role === "organizer") return "/organizer/login";

  if (role === "admin") return "/admin/login";

  return "/super-admin/login";
}

function getDashboardFallbackPath(role: Role) {
  if (role === "organizer") return "/organizer/dashboard";

  if (role === "admin") return "/admin/dashboard";

  return "/super-admin/dashboard";
}

function getDashboardSafeRedirectPath(role: Role, pathname: string) {
  const fallback = getDashboardFallbackPath(role);

  const currentPath = pathname || fallback;

  const roleRoot = `/${role}`;

  if (!currentPath.startsWith(roleRoot)) return fallback;

  if (currentPath.startsWith(getDashboardLoginPath(role))) return fallback;

  return currentPath;
}

function getDashboardAuthStorageKeys(role: Role) {
  const keys = [roleSessionKey[role]];

  if (role === "organizer") {
    keys.push("buizz-organizer-session", "buizz-organizer");
  }

  if (role === "admin") {
    keys.push("buizz-admin-session");
  }

  if (role === "super-admin") {
    keys.push("buizz-super-admin-session");
  }

  return Array.from(new Set(keys.filter(Boolean)));
}

function clearDashboardAuthSessions(role: Role) {
  if (typeof window === "undefined") return;

  getDashboardAuthStorageKeys(role).forEach((key) => {
    window.localStorage.removeItem(key);
  });

  window.dispatchEvent(new Event("buizz-auth-session-updated"));

  if (role === "organizer") {
    window.dispatchEvent(new Event("buizz-organizer-session-updated"));
  }
}

function getDashboardSessionIdentity(payload: DashboardAuthPayload) {
  return String(
    payload.email ?? payload.phone ?? payload.orgName ?? payload.name ?? "",
  ).trim();
}

function isDashboardSessionExpired(payload: DashboardAuthPayload) {
  const expiryValue = payload.expiresAt ?? payload.expiry;

  if (!expiryValue) return false;

  const expiryTime = new Date(String(expiryValue)).getTime();

  if (Number.isNaN(expiryTime)) return false;

  return Date.now() > expiryTime;
}

function isDashboardBlockedStatus(status: string) {
  const normalized = status.toLowerCase();

  return (
    normalized === "blocked" ||
    normalized === "disabled" ||
    normalized === "inactive" ||
    normalized === "suspended" ||
    normalized === "rejected"
  );
}

function readDashboardAuthSession(role: Role): DashboardAuthResult {
  if (typeof window === "undefined") return { authorized: false };

  // Try new auth session format first
  const authRole = role === "super-admin" ? "super-admin" : role as "customer" | "organizer" | "admin" | "super-admin";
  const newSession = getRoleSession(authRole);
  
  // ;
  
  if (newSession) {
    // ;
    return {
      authorized: true,
      identity: newSession.email || newSession.phone || newSession.name || "",
      status: newSession.status || "active",
      userId: newSession.userId || newSession.displayId,
    };
  }

  // ;
  // Fallback to old session format
  for (const storageKey of getDashboardAuthStorageKeys(role)) {
    const rawSession = window.localStorage.getItem(storageKey);
    // ;

    if (!rawSession) continue;

    try {
      const parsed = JSON.parse(rawSession) as DashboardAuthPayload;

      const storedRole = parsed.role ? String(parsed.role) : "";

      const status = parsed.status ? String(parsed.status) : "";

      const identity = getDashboardSessionIdentity(parsed);

      if (!identity) {
        window.localStorage.removeItem(storageKey);

        continue;
      }

      if (storedRole && storedRole !== role) {
        window.localStorage.removeItem(storageKey);

        continue;
      }

      if (isDashboardSessionExpired(parsed)) {
        window.localStorage.removeItem(storageKey);

        continue;
      }

      if (isDashboardBlockedStatus(status)) {
        window.localStorage.removeItem(storageKey);

        continue;
      }

      // ;
      return {
        authorized: true,

        identity,

        status,

        userId: String(parsed.name ?? parsed.email ?? identity ?? "").trim(),
      };
    } catch {
      window.localStorage.removeItem(storageKey);
    }
  }

  // ;
  return { authorized: false };
}

export function RoleDashboardPage({
  role,
  section,
}: {
  role: Role;
  section?: string;
}) {
  const pathname = usePathname() ?? "/";

  const router = useRouter();
  const mounted = useMounted();
  const [sessionEmail, setSessionEmail] = useState("");
  const [authChecked, setAuthChecked] = useState(false);
  const [isAuthorized, setIsAuthorized] = useState(false);
  // Direct session check without state dependency
  const currentSession = useMemo(() => readDashboardAuthSession(role), [role]);
    // Use direct session check for email as well
  const currentEmail = currentSession.authorized ? currentSession.identity : sessionEmail;
  // Direct organizer approval state check without state dependency
  const currentOrganizerApprovalState = useMemo(() => 
    role === "organizer" ? getOrganizerApprovalState() : null, [role]
  );

  const [organizerApprovalState, setOrganizerApprovalState] =
    useState<OrganizerApprovalState | null>(null);
  const effectiveOrganizerApprovalState =
    organizerApprovalState ?? currentOrganizerApprovalState;

  const storedAdminPermissions = usePermissionStore(
    (state) => state.adminPermissions["admin-ops"],
  );

  // Use the organizer ID from session for permission lookup
  const organizerId = currentSession.authorized && role === "organizer" 
    ? currentSession.userId || currentSession.identity
    : "org-festlane";

  const storedOrganizerPermissions = usePermissionStore(
    (state) => state.organizerPermissions[organizerId],
  );

  const [entityOrganizerPermissions, setEntityOrganizerPermissions] = useState<
    Partial<OrganizerPermissions>
  >({});

  const adminPermissions = {
    ...defaultAdminPermissions,
    ...(storedAdminPermissions ?? {}),
  };

  const organizerPermissions = {
    ...defaultOrganizerPermissions,
    ...(storedOrganizerPermissions ?? {}),
    ...entityOrganizerPermissions,
  };

  useEffect(() => {
    if (!mounted) return;

    const session = readDashboardAuthSession(role);

    if (!session.authorized) {
      setSessionEmail("");
      setIsAuthorized(false);
      setAuthChecked(true);
      router.replace(
        `${getDashboardLoginPath(role)}?redirect=${encodeURIComponent(getDashboardFallbackPath(role))}`,
      );
      return;
    }

    setSessionEmail(session.identity);
    setIsAuthorized(true);
    setAuthChecked(true);

    if (role === "organizer") setOrganizerApprovalState(getOrganizerApprovalState());
  }, [mounted, role, router]);

  // Debug: Monitor state changes
  useEffect(() => {
    // ;
  }, [authChecked, isAuthorized]);

  useEffect(() => {
    if (role !== "organizer") return;

    const syncApprovalState = () =>
      setOrganizerApprovalState(getOrganizerApprovalState());

    syncApprovalState();

    window.addEventListener("storage", syncApprovalState);

    window.addEventListener(
      ORGANIZER_APPLICATIONS_UPDATED_EVENT,

      syncApprovalState,
    );

    window.addEventListener(
      "buizz-organizer-approval-updated",
      syncApprovalState,
    );

    return () => {
      window.removeEventListener("storage", syncApprovalState);

      window.removeEventListener(
        ORGANIZER_APPLICATIONS_UPDATED_EVENT,

        syncApprovalState,
      );

      window.removeEventListener(
        "buizz-organizer-approval-updated",

        syncApprovalState,
      );
    };
  }, [role]);

  useEffect(() => {
    if (role !== "organizer") return;

    setEntityOrganizerPermissions(readOrganizerEntityPermissionsForStore(organizerId));
  }, [role, organizerId]);

  const nav = useMemo(() => {
    const addHistoryItem = (items: NavItem[]) => {
      const historyHref = `/${role}/history`;

      if (
        items.some((item) => item.type !== "group" && item.href === historyHref)
      ) {
        return items;
      }

      const historyItem = {
        label: "History",

        href: historyHref,

        icon: History,
      } as NavItem;

      const settingsIndex = items.findIndex(
        (item) => item.type !== "group" && item.href?.endsWith("/settings"),
      );

      if (settingsIndex === -1) {
        return [...items, historyItem];
      }

      return [
        ...items.slice(0, settingsIndex),

        historyItem,

        ...items.slice(settingsIndex),
      ];
    };

    if (role === "super-admin") {
      return addHistoryItem(superAdminNav);
    }

    if (role === "admin") {
      const filteredAdminNav = adminNav.filter((item) => {
        if (item.type !== "group" && item.href?.endsWith("/reports")) {
          return false;
        }

        return (
          item.type === "group" ||
          !item.permission ||
          adminPermissions[item.permission as AdminPermissionKey]
        );
      });

      return addHistoryItem(filteredAdminNav);
    }

    const filteredOrganizerNav = organizerNav.filter(
      (item) =>
        item.type === "group" ||
        !item.permission ||
        organizerPermissions[item.permission as OrganizerPermissionKey],
    );

    return addHistoryItem(filteredOrganizerNav);
  }, [role, adminPermissions, organizerPermissions]);

  // The client pathname changes immediately during a soft navigation, while
  // the dynamic server-page prop can briefly retain the previous section.
  // Prefer pathname so organizer pages switch without requiring a reload.
  const currentSection =
    pathname.split("/").filter(Boolean).at(-1) ?? section ?? "dashboard";

  const currentNav = nav.find(
    (item) =>
      item.type !== "group" &&
      item.href &&
      (item.href === pathname || item.href.endsWith(`/${currentSection}`)),
  );

  const currentAllowed =
    !currentNav?.permission ||
    role === "super-admin" ||
    (role === "admin"
      ? adminPermissions[currentNav.permission as AdminPermissionKey]
      : organizerPermissions[currentNav.permission as OrganizerPermissionKey]);

  // Use direct session check instead of state-based check
  const shouldShowLoader = !currentSession.authorized;
  
  if (shouldShowLoader) {
    // ;
    return <DashboardHydrationLoader role={role} />;
  }

  if (
    role === "organizer" &&
    effectiveOrganizerApprovalState &&
    !canAccessOrganizerDashboard(effectiveOrganizerApprovalState)
  ) {
    // ;
    return <DashboardLockNotice />;
  }

  if (!currentAllowed) {
    return (
      <DashboardShell role={role} nav={nav} email={currentEmail}>
        <AccessBlocked role={role} />
      </DashboardShell>
    );
  }

  return (
    <DashboardShell role={role} nav={nav} email={currentEmail}>
      {role === "super-admin" ? (
        <SuperAdminSection section={currentSection} />
      ) : null}

      {role === "admin" ? <AdminSection section={currentSection} /> : null}

      {role === "organizer" ? (
        currentSection === "history" ? (
          <HistoryView role="organizer" />
        ) : (
          <OrganizerSection section={currentSection} />
        )
      ) : null}
    </DashboardShell>
  );
}

export function OrganizerOnboardingPage() {
  const router = useRouter();

  const [step, setStep] = useState(0);

  const steps = ["General Information", "Documents", "Agreement", "Signature"];

  const next = () => {
    if (step < steps.length - 1) {
      setStep((value) => value + 1);

      return;
    }

    window.localStorage.setItem(
      "buizz-organizer-approval-status",
      "pending-admin",
    );

    router.push("/organizer/application-status");
  };

  return (
    <main className="min-h-screen bg-[var(--app-background)] px-4 py-8 text-[var(--app-foreground)] sm:px-6">
      <section className="mx-auto max-w-[1500px]">
        <TopBrand label="Organizer Onboarding" />

        <div className="mt-6 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] p-5 shadow-[0_18px_58px_rgba(0,0,0,0.12)]">
          <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
            <div>
              <h1 className="text-3xl font-black">
                Complete organizer onboarding
              </h1>

              <p className="mt-2 text-sm font-semibold text-[var(--app-muted)]">
                Submit organization details, documents, and agreement for
                approval.
              </p>
            </div>

            <span className="rounded-md bg-[var(--color-brand-primary)]/10 px-3 py-2 text-xs font-black text-[var(--color-brand-primary)]">
              Step {step + 1} of {steps.length}
            </span>
          </div>

          <div className="mt-6 grid gap-2 sm:grid-cols-4">
            {steps.map((item, index) => (
              <div
                key={item}
                className={`rounded-md border p-3 ${index <= step ? "border-[var(--color-brand-primary)] bg-[var(--color-brand-primary)]/10" : "border-[var(--app-border)] bg-[var(--app-subtle)]"}`}
              >
                <p className="text-xs font-black">{item}</p>
              </div>
            ))}
          </div>

          <OnboardingStep step={step} />

          <div className="mt-6 flex flex-wrap gap-3">
            <button
              type="button"
              disabled={step === 0}
              onClick={() => setStep((value) => Math.max(0, value - 1))}
              className="inline-flex min-h-11 items-center rounded-md border border-[var(--app-border)] px-5 text-sm font-black disabled:opacity-50"
            >
              Back
            </button>

            <button
              type="button"
              onClick={next}
              className="inline-flex min-h-11 items-center rounded-md bg-[var(--color-brand-primary)] px-5 text-sm font-black text-white"
            >
              {step === steps.length - 1 ? "Submit Application" : "Continue"}
            </button>
          </div>
        </div>
      </section>
    </main>
  );
}

