export function RoleAuthPage({
  role,

  mode,
}: {
  role: ControlAuthRole;

  mode: ControlAuthMode;
}) {
  if (mode === "forgot-password") {
    return <ControlPasswordRecoveryPage role={role} reset={false} />;
  }

  if (mode === "reset-password") {
    return <ControlPasswordRecoveryPage role={role} reset />;
  }

  if (mode === "signup") {
    return <ControlAccountLockedPage role={role} />;
  }

  return <ControlLoginPage role={role} />;
}

