function ControlLoginPage({ role }: { role: ControlAuthRole }) {
  const router = useRouter();

  const searchParams = useSearchParams();

  const config = controlAuthConfig[role];

  const [email, setEmail] = useState("");

  const [password, setPassword] = useState("");

  const [rememberMe, setRememberMe] = useState(true);

  const [showPassword, setShowPassword] = useState(false);

  const [error, setError] = useState("");

  const [isSubmitting, setIsSubmitting] = useState(false);

  const [adminLogin] = useAdminLoginMutation();

  const [userLogin] = useLoginMutation();

  const login = async () => {
    const trimmedEmail = email.trim().toLowerCase();

    setError("");

    if (!trimmedEmail || !trimmedEmail.includes("@")) {
      setError("Please enter a valid admin email address.");

      return;
    }

    if (!password.trim()) {
      setError("Please enter your password.");

      return;
    }

    setIsSubmitting(true);

    [
      "buizz-admin-session",
      "buizz-super-admin-session",
      "buizz-super_admin-session",
    ].forEach((k) => {
      window.localStorage.removeItem(k);
    });

    try {
      let realToken: string | undefined;

      let userName = "Admin";

      if (role === "super-admin") {
        // Super admin lives in users table — use /auth/login

        const result = await userLogin({
          email: trimmedEmail,
          password,
        }).unwrap();

        const userData = result.data?.user;

        if (userData?.role !== "super_admin") {
          setError(
            "Access denied. This account does not have super admin privileges.",
          );

          return;
        }

        realToken = result.data?.token;

        userName = userData?.name ?? "Super Admin";
      } else {
        // Admin lives in admins table — use /admin/login

        const result = await adminLogin({
          email: trimmedEmail,
          password,
        }).unwrap();

        realToken = result.data?.token;

        userName = result.data?.user?.name ?? "Admin";
      }

      saveControlAuthSession({
        role,

        email: trimmedEmail,

        name: userName,

        rememberMe,

        token: realToken,
      });

      const redirectPath = getControlSafeRedirectPath(
        searchParams?.get("redirect") ?? null,

        role,
      );

      router.replace(redirectPath);
    } catch (err: any) {
      setError(
        err.data?.message || "Login failed. Please check your credentials.",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <ControlAuthShell
      role={role}
      title={role === "super-admin" ? "Super Admin Login" : "Admin Login"}
      description={
        role === "super-admin"
          ? "Control admins, approvals, permissions, revenue, settlements and platform settings."
          : "Manage assigned reviews, bookings, support, venues and attendee operations."
      }
      icon={
        role === "super-admin" ? (
          <Crown className="size-4" />
        ) : (
          <ShieldCheck className="size-4" />
        )
      }
      backHref={`/${role}`}
      backLabel={config.backLabel}
    >
      <div className="grid gap-2">
        <button type="button" className={controlAuthGoogleButtonClass}>
          <ControlGoogleIcon className="size-4 shrink-0" />

          <span>Google</span>
        </button>
      </div>

      <ControlAuthDivider />

      <div className="grid gap-3">
        <label className={controlAuthLabelClass}>
          Email Address
          <div className={controlAuthInputWrapClass}>
            <Mail className="size-4 shrink-0 text-slate-400" />

            <input
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              type="email"
              placeholder="Enter email address"
              className={controlAuthInputClass}
            />
          </div>
        </label>

        <label className={controlAuthLabelClass}>
          Password
          <div className={controlAuthInputWrapClass}>
            <Lock className="size-4 shrink-0 text-slate-400" />

            <input
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              type={showPassword ? "text" : "password"}
              placeholder="Enter password"
              className={controlAuthInputClass}
            />

            <button
              type="button"
              onClick={() => setShowPassword((current) => !current)}
              className="text-slate-400 transition hover:text-[#070a1a]"
              aria-label={showPassword ? "Hide password" : "Show password"}
            >
              {showPassword ? (
                <EyeOff className="size-4" />
              ) : (
                <Eye className="size-4" />
              )}
            </button>
          </div>
        </label>
      </div>

      <div className="mt-3 flex items-center justify-between gap-2">
        <label className="flex min-w-0 items-center gap-2 text-[11px] font-bold text-slate-500">
          <input
            type="checkbox"
            checked={rememberMe}
            onChange={(event) => setRememberMe(event.target.checked)}
            className="size-3.5 shrink-0 rounded border-slate-300 accent-[#ec1b72]"
          />

          <span className="truncate">Keep me logged in</span>
        </label>

        <Link
          href={`/${role}/forgot-password`}
          className="shrink-0 text-[11px] font-black text-[#ec1b72] underline-offset-4 transition hover:text-[#070a1a] hover:underline"
        >
          Forgot Password?
        </Link>
      </div>

      {error ? <ControlAuthErrorMessage message={error} /> : null}

      <button
        type="button"
        onClick={login}
        disabled={isSubmitting}
        className={`${controlAuthPrimaryButtonClass} mt-4`}
      >
        {isSubmitting ? "Checking..." : "Login"}
      </button>

      <p className="mt-4 text-center text-[11px] font-bold leading-5 text-slate-500 sm:text-xs">
        {role === "admin"
          ? "Admin accounts are created by Super Admin."
          : "Super Admin access is private and protected."}
      </p>
    </ControlAuthShell>
  );
}

function ControlPasswordRecoveryPage({
  role,

  reset,
}: {
  role: ControlAuthRole;

  reset: boolean;
}) {
  const router = useRouter();

  const config = controlAuthConfig[role];

  const [email, setEmail] = useState("");

  const [otp, setOtp] = useState("");

  const [newPassword, setNewPassword] = useState("");

  const [confirmPassword, setConfirmPassword] = useState("");

  const [message, setMessage] = useState("");

  const sendReset = () => {
    if (!email.trim() || !email.includes("@")) {
      setMessage("Enter a valid registered email address.");

      return;
    }

    setMessage("If this email is registered, a reset link will be sent.");
  };

  const resetPassword = () => {
    if (!otp.trim()) {
      setMessage("Enter the OTP sent to your email.");

      return;
    }

    if (newPassword.length < 6) {
      setMessage("Password must be at least 6 characters.");

      return;
    }

    if (newPassword !== confirmPassword) {
      setMessage("New password and confirm password do not match.");

      return;
    }

    setMessage("Password reset submitted. Login with your new password.");

    window.setTimeout(() => router.replace(`/${role}/login`), 700);
  };

  return (
    <ControlAuthShell
      role={role}
      title={reset ? "Reset Password" : "Forgot Password"}
      description={
        reset
          ? `Enter the OTP sent to your email and create a new secure password.`
          : "Enter your registered email address to receive a password reset OTP."
      }
      icon={<KeyRound className="size-5" />}
      backHref={`/${role}/login`}
      backLabel={`Back to ${config.badge.toLowerCase()} login`}
    >
      {!reset ? (
        <div className="grid gap-3">
          <label className={controlAuthLabelClass}>
            Registered Email
            <div className={controlAuthInputWrapClass}>
              <Mail className="size-4 shrink-0 text-white/64 lg:text-slate-400" />

              <input
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                type="email"
                placeholder="Enter registered email"
                className={controlAuthInputClass}
              />
            </div>
          </label>

          {message ? <ControlAuthInfoMessage message={message} /> : null}

          <button
            type="button"
            onClick={sendReset}
            className={controlAuthPrimaryButtonClass}
          >
            Send Reset OTP
          </button>

          <Link
            href={`/${role}/reset-password`}
            className={controlAuthSecondaryButtonClass}
          >
            I Have OTP
          </Link>
        </div>
      ) : (
        <div className="grid gap-3">
          <ControlAuthTextInput
            label="Demo OTP"
            value={otp}
            onChange={setOtp}
            placeholder="123456"
            icon={<ShieldCheck className="size-4" />}
          />

          <ControlAuthTextInput
            label="New Password"
            value={newPassword}
            onChange={setNewPassword}
            type="password"
            placeholder="Create new password"
            icon={<Lock className="size-4" />}
          />

          <ControlAuthTextInput
            label="Confirm Password"
            value={confirmPassword}
            onChange={setConfirmPassword}
            type="password"
            placeholder="Confirm new password"
            icon={<Lock className="size-4" />}
          />

          {message ? <ControlAuthInfoMessage message={message} /> : null}

          <button
            type="button"
            onClick={resetPassword}
            className={controlAuthPrimaryButtonClass}
          >
            Save New Password
          </button>
        </div>
      )}
    </ControlAuthShell>
  );
}

