function saveControlAuthSession({
  role,

  email,

  name,

  rememberMe,

  token,
}: {
  role: ControlAuthRole;

  email: string;

  name: string;

  rememberMe: boolean;

  token?: string;
}) {
  const config = controlAuthConfig[role];

  const now = new Date();

  const expiresAt = new Date(
    now.getTime() +
      (rememberMe ? controlAuthRememberTtlMs : controlAuthShortTtlMs),
  ).toISOString();

  const sessionPayload = {
    version: 1,
    sessionId: `${role}-${Date.now()}`,
    role,
    email,
    name,
    status: "active",
    permissions: config.permissions,
    token,
    rememberMe,
    issuedAt: now.toISOString(),
    loggedInAt: now.toISOString(),
    lastActivityAt: now.toISOString(),
    expiresAt,
  };

  const storageKeys = new Set<string>([
    roleSessionKey[role],

    role === "admin" ? "buizz-admin-session" : "buizz-super-admin-session",
  ]);

  storageKeys.forEach((storageKey) => {
    window.localStorage.setItem(storageKey, JSON.stringify(sessionPayload));
  });
  window.dispatchEvent(new Event("buizz-auth-session-updated"));
  window.dispatchEvent(new Event("storage"));
}

function getControlSafeRedirectPath(
  value: string | null,
  role: ControlAuthRole,
) {
  const fallback =
    role === "admin" ? "/admin/dashboard" : "/super-admin/dashboard";

  if (!value) return fallback;

  try {
    const decoded = decodeURIComponent(value);

    const roleRoot = role === "admin" ? "/admin" : "/super-admin";

    const loginPath = role === "admin" ? "/admin/login" : "/super-admin/login";

    if (decoded.startsWith(roleRoot) && !decoded.startsWith(loginPath)) {
      return decoded;
    }
  } catch {
    // Keep safe fallback path.
  }

  return fallback;
}

type RatingModerationStatus = "pending" | "approved" | "rejected";

type RatingModerationSource = "web" | "ticket_wallet" | "post_event_email";

type RatingModerationItem = {
  id: string;

  bookingId: string;

  eventId: string;

  eventName: string;

  customerName: string;

  customerEmail: string;

  rating: number;

  comment: string;

  source: RatingModerationSource;

  status: RatingModerationStatus;

  publicVisible: boolean;

  submittedAt: string;

  reviewedAt?: string;

  reviewedBy?: string;

  reviewedRole?: "admin" | "super-admin";

  moderationNote?: string;
};

const ratingModerationStorageKey = "buizz-rating-moderation-records";

const initialRatingModerationItems: RatingModerationItem[] = [];

function readRatingModerationItems() {
  if (typeof window === "undefined") return initialRatingModerationItems;

  try {
    const parsed = JSON.parse(
      window.localStorage.getItem(ratingModerationStorageKey) ?? "null",
    ) as RatingModerationItem[] | null;

    if (Array.isArray(parsed)) return parsed;
  } catch {
    // Keep frontend safe if stored data is corrupted.
  }

  return initialRatingModerationItems;
}

function saveRatingModerationItems(items: RatingModerationItem[]) {
  if (typeof window === "undefined") return;

  window.localStorage.setItem(
    ratingModerationStorageKey,
    JSON.stringify(items),
  );
}

function formatRatingModerationDate(value: string) {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return value;

  return date.toLocaleString("en-IN", {
    day: "2-digit",

    month: "short",

    year: "numeric",

    hour: "2-digit",

    minute: "2-digit",
  });
}

function formatRatingSource(source: RatingModerationSource) {
  if (source === "ticket_wallet") return "Ticket Wallet";

  if (source === "post_event_email") return "Post-event Email";

  return "Website";
}

function RatingModerationBadge({ status }: { status: RatingModerationStatus }) {
  const tone =
    status === "approved"
      ? "border-[#22C55E]/25 bg-[#22C55E]/10 text-[#16A34A]"
      : status === "rejected"
        ? "border-[var(--color-brand-primary)]/25 bg-[var(--color-brand-primary)]/10 text-[var(--color-brand-primary)]"
        : "border-[var(--color-brand-accent)]/35 bg-[var(--color-brand-accent)]/10 text-[var(--color-brand-accent)]";

  return (
    <span
      className={`inline-flex min-h-8 shrink-0 items-center rounded-full border px-3 text-[11px] font-black uppercase tracking-[0.04em] ${tone}`}
    >
      {status}
    </span>
  );
}

function RatingReviewWorkspace({
  role,

  canApprove = true,
}: {
  role: "admin" | "super-admin";

  canApprove?: boolean;
}) {
  const [items, setItems] = useState<RatingModerationItem[]>([]);

  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<
    "all" | RatingModerationStatus
  >("pending");
  const [rejectTarget, setRejectTarget] = useState<RatingModerationItem | null>(
    null,
  );
  const [rejectReason, setRejectReason] = useState("");

  const { loadingKey, successMessage, errorMessage, runAction } =
    useActionFeedback();

  const actorName = role === "super-admin" ? "Super Admin" : "Admin";

  const counts = {
    total: items.length,

    pending: items.filter((item) => item.status === "pending").length,

    approved: items.filter((item) => item.status === "approved").length,

    rejected: items.filter((item) => item.status === "rejected").length,

    publicVisible: items.filter((item) => item.publicVisible).length,
  };

  const filteredItems = items.filter((item) => {
    const query = search.trim().toLowerCase();

    const matchesSearch =
      !query ||
      item.id.toLowerCase().includes(query) ||
      item.bookingId.toLowerCase().includes(query) ||
      item.eventId.toLowerCase().includes(query) ||
      item.eventName.toLowerCase().includes(query) ||
      item.customerName.toLowerCase().includes(query) ||
      item.customerEmail.toLowerCase().includes(query) ||
      item.comment.toLowerCase().includes(query);

    const matchesStatus =
      statusFilter === "all" || item.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const updateRatingStatus = (
    id: string,

    status: RatingModerationStatus,

    moderationNote: string,
  ) => {
    setItems((current) =>
      current.map((item) =>
        item.id === id
          ? {
              ...item,

              status,

              publicVisible: status === "approved",

              reviewedAt: new Date().toISOString(),

              reviewedBy: actorName,

              reviewedRole: role,

              moderationNote,
            }
          : item,
      ),
    );
  };

  const handleApprove = (item: RatingModerationItem) => {
    if (!canApprove) {
      alert("Rating approval permission is disabled for this admin.");

      return;
    }

    void runAction(
      `approve-rating-${item.id}`,

      () =>
        updateRatingStatus(
          item.id,

          "approved",

          "Approved after moderation review.",
        ),

      "Rating approved.",
    );
  };

  const handleReject = () => {
    if (!rejectTarget || !rejectReason.trim()) return;

    if (!canApprove) {
      alert("Rating approval permission is disabled for this admin.");

      return;
    }

    void runAction(
      `reject-rating-${rejectTarget.id}`,

      () => {
        updateRatingStatus(rejectTarget.id, "rejected", rejectReason.trim());

        setRejectTarget(null);

        setRejectReason("");
      },

      "Rating rejected.",
    );
  };

  const statCards = [
    {
      title: "Pending Review",

      value: counts.pending,

      icon: Clock,

      tone: "warning" as const,
    },

    {
      title: "Approved Public",

      value: counts.approved,

      icon: CheckCircle2,

      tone: "success" as const,
    },

    {
      title: "Rejected Hidden",

      value: counts.rejected,

      icon: XCircle,

      tone: "danger" as const,
    },

    {
      title: "Total Records",

      value: counts.total,

      icon: Star,

      tone: "brand" as const,
    },
  ];

  const getStatToneClass = (
    tone: "warning" | "success" | "danger" | "brand",
  ) => {
    if (tone === "success")
      return "bg-[#22C55E]/10 text-[#16A34A] ring-[#22C55E]/20";

    if (tone === "danger")
      return "bg-[var(--color-brand-primary)]/10 text-[var(--color-brand-primary)] ring-[var(--color-brand-primary)]/20";

    if (tone === "brand")
      return "bg-[var(--color-brand-secondary)]/10 text-[var(--color-brand-secondary)] ring-[var(--color-brand-secondary)]/20";

    return "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)] ring-[var(--color-brand-accent)]/25";
  };

  return (
    <section
      aria-label="Customer rating approval queue"
      className="mx-auto grid w-full min-w-0 max-w-[1600px] gap-4 sm:gap-5"
    >
      <section className="grid min-w-0 grid-cols-4 gap-1.5 sm:gap-3 lg:gap-4">
        {statCards.map((stat) => {
          const Icon = stat.icon;

          return (
            <article
              key={stat.title}
              className="min-w-0 rounded-[18px] border border-[var(--app-border)] bg-[var(--app-elevated)] px-2 py-3 shadow-[0_10px_28px_rgba(15,23,42,0.06)] sm:rounded-[24px] sm:p-4"
            >
              <div className="flex min-w-0 items-center justify-between gap-1 sm:gap-3">
                <span
                  className={`hidden shrink-0 place-items-center rounded-2xl ring-1 sm:grid sm:size-10 ${getStatToneClass(stat.tone)}`}
                >
                  <Icon className="size-4" />
                </span>

                <span className="min-w-0 text-xl font-black leading-none text-[var(--app-foreground)] sm:ml-auto sm:text-right sm:text-3xl">
                  {stat.value}
                </span>
              </div>

              <p className="mt-2 min-w-0 text-[10px] font-black leading-tight text-[var(--app-foreground)] [overflow-wrap:normal] sm:mt-4 sm:text-base lg:text-lg">
                {stat.title}
              </p>
            </article>
          );
        })}
      </section>

      {!canApprove ? (
        <section className="rounded-[24px] border border-[var(--color-brand-accent)]/30 bg-[var(--color-brand-accent)]/10 p-4 text-sm font-semibold leading-6 text-[var(--app-foreground)] sm:rounded-[1.75rem]">
          <div className="grid gap-3 sm:grid-cols-[auto_minmax(0,1fr)] sm:items-start">
            <AlertCircle className="size-5 shrink-0 text-[var(--color-brand-accent)]" />

            <p className="break-words">
              This admin can view rating records, but approve/reject permission
              is disabled.
            </p>
          </div>
        </section>
      ) : null}

      <section className="min-w-0 overflow-hidden rounded-[24px] border border-[var(--app-border)] bg-[var(--app-elevated)] shadow-[0_18px_54px_rgba(15,23,42,0.08)] sm:rounded-[2rem]">
        <div className="grid min-w-0 gap-4 border-b border-[var(--app-border)] p-4 sm:p-5 xl:grid-cols-[minmax(0,1fr)_auto] xl:items-end">
          <div className="min-w-0">
            <p className="text-[10px] font-black uppercase tracking-[0.16em] text-[var(--color-brand-primary)] sm:text-[11px] sm:tracking-[0.18em]">
              Moderation Records
            </p>

            <h2 className="mt-1 break-words text-xl font-black leading-tight tracking-[-0.03em] text-[var(--app-foreground)] sm:text-2xl">
              Customer rating approval queue
            </h2>
          </div>

          <div className="grid min-w-0 gap-2 sm:grid-cols-[minmax(0,260px)_160px] xl:w-[460px]">
            <input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search rating, booking, event, customer..."
              className={dashboardInputClass}
            />

            <select
              value={statusFilter}
              onChange={(event) =>
                setStatusFilter(
                  event.target.value as "all" | RatingModerationStatus,
                )
              }
              className={dashboardSelectClass}
            >
              <option value="all">All Status</option>

              <option value="pending">Pending</option>

              <option value="approved">Approved</option>

              <option value="rejected">Rejected</option>
            </select>
          </div>
        </div>

        <ActionFeedback
          successMessage={successMessage}
          errorMessage={errorMessage}
        />

        {filteredItems.length ? (
          <div className="grid gap-3 p-3 md:hidden">
            {filteredItems.map((item) => (
              <article
                key={`mobile-${item.id}`}
                className="rounded-[22px] border border-[var(--app-border)] bg-[var(--app-subtle)] p-4"
              >
                <div className="flex min-w-0 items-start justify-between gap-3">
                  <div className="min-w-0">
                    <p className="text-xs font-black uppercase tracking-[0.12em] text-[var(--color-brand-primary)]">
                      {item.id}
                    </p>

                    <h3 className="mt-1 break-words text-lg font-black leading-tight">
                      {item.eventName}
                    </h3>

                    <p className="mt-1 break-words text-xs font-semibold text-[var(--app-muted)]">
                      {item.bookingId} • {item.eventId}
                    </p>
                  </div>

                  <RatingModerationBadge status={item.status} />
                </div>

                <div className="mt-4 grid grid-cols-2 gap-2">
                  {[
                    {
                      label: "Customer",
                      value: item.customerName,
                      sub: item.customerEmail,
                    },

                    {
                      label: "Rating",
                      value: `${item.rating}/5`,
                      sub: formatRatingSource(item.source),
                    },

                    {
                      label: "Submitted",
                      value: formatRatingModerationDate(item.submittedAt),
                      sub: `Public: ${item.publicVisible ? "Yes" : "No"}`,
                    },

                    {
                      label: "Reviewer",
                      value: item.reviewedBy ?? "Not reviewed",
                      sub: item.reviewedAt
                        ? formatRatingModerationDate(item.reviewedAt)
                        : "Pending moderation",
                    },
                  ].map((row) => (
                    <div
                      key={row.label}
                      className="min-w-0 rounded-2xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-3"
                    >
                      <p className="text-[10px] font-black uppercase tracking-[0.08em] text-[var(--app-muted)]">
                        {row.label}
                      </p>

                      <p className="mt-1 min-w-0 break-words text-sm font-black leading-5 text-[var(--app-foreground)]">
                        {row.value}
                      </p>

                      <p className="mt-1 min-w-0 break-words text-[11px] font-semibold leading-4 text-[var(--app-muted)]">
                        {row.sub}
                      </p>
                    </div>
                  ))}
                </div>

                <div className="mt-3 rounded-2xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-3">
                  <p className="text-[10px] font-black uppercase tracking-[0.10em] text-[var(--app-muted)]">
                    Feedback
                  </p>

                  <p className="mt-2 break-words text-sm font-semibold leading-6">
                    {item.comment}
                  </p>

                  {item.moderationNote ? (
                    <p className="mt-2 break-words text-xs font-semibold leading-5 text-[var(--app-muted)]">
                      Note: {item.moderationNote}
                    </p>
                  ) : null}
                </div>

                <div className="mt-4 grid grid-cols-2 gap-2">
                  <LoadingButton
                    loading={loadingKey === `approve-rating-${item.id}`}
                    loadingText="Approving..."
                    disabled={!canApprove || item.status === "approved"}
                    onClick={() => handleApprove(item)}
                    className="min-h-10 rounded-xl bg-[#22C55E] px-4 text-xs font-black text-white disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    Approve
                  </LoadingButton>

                  <button
                    type="button"
                    disabled={!canApprove || item.status === "rejected"}
                    onClick={() => {
                      setRejectTarget(item);

                      setRejectReason("");
                    }}
                    className="min-h-10 rounded-xl bg-[var(--color-brand-primary)] px-4 text-xs font-black text-white disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    Reject
                  </button>
                </div>
              </article>
            ))}
          </div>
        ) : (
          <div className="grid min-h-44 place-items-center p-6 text-center">
            <div>
              <Star className="mx-auto size-10 text-[var(--app-muted)]" />

              <p className="mt-3 text-lg font-black">No rating records found</p>

              <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
                Change search or status filter.
              </p>
            </div>
          </div>
        )}

        {filteredItems.length ? (
          <div className="hidden overflow-x-auto md:block">
            <table className="w-full min-w-[1120px] text-left text-sm">
              <thead>
                <tr className="border-y border-[var(--app-border)] bg-[var(--app-subtle)] text-xs font-black uppercase tracking-[0.06em] text-[var(--app-muted)]">
                  <th className="w-[210px] px-4 py-4">Rating Record</th>

                  <th className="w-[190px] px-4 py-4">Customer</th>

                  <th className="w-[320px] px-4 py-4">Feedback</th>

                  <th className="w-[150px] px-4 py-4">Source</th>

                  <th className="w-[130px] px-4 py-4">Status</th>

                  <th className="w-[190px] px-4 py-4">Reviewer</th>

                  <th className="w-[170px] px-4 py-4">Actions</th>
                </tr>
              </thead>

              <tbody>
                {filteredItems.map((item) => (
                  <tr
                    key={item.id}
                    className="border-b border-[var(--app-border)] align-top last:border-0 hover:bg-[var(--app-subtle)]/70"
                  >
                    <td className="px-4 py-4">
                      <p className="font-black text-[var(--app-foreground)]">
                        {item.id}
                      </p>

                      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                        {item.bookingId}
                      </p>

                      <p className="mt-1 max-w-[210px] text-xs font-semibold leading-5 text-[var(--app-muted)]">
                        {item.eventName}
                      </p>

                      <p className="mt-1 text-[11px] font-black text-[var(--color-brand-secondary)]">
                        {item.eventId}
                      </p>
                    </td>

                    <td className="px-4 py-4">
                      <p className="font-black">{item.customerName}</p>

                      <p className="mt-1 max-w-[170px] break-all text-xs font-semibold text-[var(--app-muted)]">
                        {item.customerEmail}
                      </p>
                    </td>

                    <td className="px-4 py-4">
                      <p className="font-black">{item.rating}/5</p>

                      <p className="mt-2 max-w-[300px] text-sm font-semibold leading-6 text-[var(--app-foreground)]">
                        {item.comment}
                      </p>

                      <p className="mt-2 text-xs font-semibold text-[var(--app-muted)]">
                        Submitted {formatRatingModerationDate(item.submittedAt)}
                      </p>
                    </td>

                    <td className="px-4 py-4">
                      <p className="font-black">
                        {formatRatingSource(item.source)}
                      </p>

                      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                        Public: {item.publicVisible ? "Yes" : "No"}
                      </p>
                    </td>

                    <td className="px-4 py-4">
                      <RatingModerationBadge status={item.status} />
                    </td>

                    <td className="px-4 py-4">
                      <p className="font-black">
                        {item.reviewedBy ?? "Not reviewed"}
                      </p>

                      <p className="mt-1 max-w-[170px] text-xs font-semibold leading-5 text-[var(--app-muted)]">
                        {item.reviewedAt
                          ? formatRatingModerationDate(item.reviewedAt)
                          : "Pending moderation"}
                      </p>

                      {item.moderationNote ? (
                        <p className="mt-2 max-w-[190px] text-xs font-semibold leading-5 text-[var(--app-muted)]">
                          {item.moderationNote}
                        </p>
                      ) : null}
                    </td>

                    <td className="px-4 py-4">
                      <div className="grid min-w-[150px] grid-cols-2 gap-2">
                        <LoadingButton
                          loading={loadingKey === `approve-rating-${item.id}`}
                          loadingText="Approving..."
                          disabled={!canApprove || item.status === "approved"}
                          onClick={() => handleApprove(item)}
                          className="min-h-10 rounded-xl bg-[#22C55E] px-3 text-xs font-black text-white disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          Approve
                        </LoadingButton>

                        <button
                          type="button"
                          disabled={!canApprove || item.status === "rejected"}
                          onClick={() => {
                            setRejectTarget(item);

                            setRejectReason("");
                          }}
                          className="min-h-10 rounded-xl bg-[var(--color-brand-primary)] px-3 text-xs font-black text-white disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          Reject
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : null}
      </section>

      {rejectTarget ? (
        <ResponsiveModalShell
          title="Reject rating"
          subtitle={`Add moderation reason for ${rejectTarget.id}.`}
          onClose={() => {
            setRejectTarget(null);

            setRejectReason("");
          }}
        >
          <div className="grid gap-4">
            <div className="rounded-2xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-4">
              <p className="text-sm font-black">{rejectTarget.eventName}</p>

              <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                {rejectTarget.bookingId} • {rejectTarget.customerName}
              </p>

              <p className="mt-3 text-sm font-semibold leading-6">
                {rejectTarget.comment}
              </p>
            </div>

            <textarea
              value={rejectReason}
              onChange={(event) => setRejectReason(event.target.value)}
              placeholder="Enter moderation reason..."
              className="min-h-32 w-full rounded-2xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-4 text-sm font-semibold outline-none focus:border-[var(--color-brand-primary)]"
            />

            {!rejectReason.trim() ? (
              <p className="text-xs font-semibold text-[var(--color-brand-primary)]">
                Rejection reason is required.
              </p>
            ) : null}

            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => {
                  setRejectTarget(null);

                  setRejectReason("");
                }}
                className={dashboardSecondaryButtonClass}
              >
                Cancel
              </button>

              <LoadingButton
                loading={loadingKey === `reject-rating-${rejectTarget.id}`}
                loadingText="Rejecting..."
                disabled={!rejectReason.trim()}
                onClick={handleReject}
                className="min-h-10 rounded-xl bg-[var(--color-brand-primary)] px-4 text-xs font-black text-white disabled:cursor-not-allowed disabled:opacity-50"
              >
                Reject Rating
              </LoadingButton>
            </div>
          </div>
        </ResponsiveModalShell>
      ) : null}
    </section>
  );
}

type TicketTemplateStatus = "draft" | "published";

type TicketPreviewMode = "desktop" | "mobile" | "print";

type TicketListingType = "event" | "activity" | "play";

type TicketEditorTab = "design" | "content" | "labels" | "security";

type TicketSeatGroup = {
  section: string;

  seatNumbers: string[];

  amount: number;
};

type TicketSeatInput = {
  section: string;

  seatNumber: string;

  amount: number;
};

type OrganizerTicketBranding = {
  organizerName: string;

  organizerLogoUrl: string;

  eventImageUrl: string;
};

type TicketSecuritySettings = {
  lockBuizzBranding: boolean;

  lockQrCode: boolean;

  lockBookingId: boolean;

  lockSeatDetails: boolean;

  lockAmountPaid: boolean;

  requireDesignApproval: boolean;

  allowOrganizerLogoUpdate: boolean;

  allowOrganizerEventImageUpdate: boolean;

  pdfDownloadEnabled: boolean;

  whatsappShareEnabled: boolean;

  watermarkLocked: boolean;
};

type TicketTemplateSettings = {
  primaryColor: string;

  secondaryColor: string;

  accentColor: string;

  overlayColor: string;

  overlayOpacity: number;

  fallbackBackgroundImage: string;

  useEventImage: boolean;

  backgroundPosition: "center" | "top" | "bottom";

  backgroundSize: "cover" | "contain";

  labels: {
    passTitle: string;

    statusBadge: string;

    bookingId: string;

    seatHeading: string;

    totalAmount: string;

    qrHelper: string;

    instruction: string;

    verifiedFooter: string;
  };

  visibility: {
    organizerLogo: boolean;

    organizerName: boolean;

    eventImage: boolean;

    category: boolean;

    venue: boolean;

    socialShareInPdf: boolean;
  };

  security: TicketSecuritySettings;

  status: TicketTemplateStatus;

  lastUpdatedAt: string;

  lastUpdatedBy: string;
};

type TicketPreviewData = {
  bookingId: string;

  ticketStatus: "Valid";

  listingType: TicketListingType;

  title: string;

  category: string;

  organizer: OrganizerTicketBranding;

  date: string;

  time: string;

  venueName: string;

  city: string;

  qrValue: string;

  seatGroups: TicketSeatGroup[];

  totalSeats: number;

  totalAmountPaid: number;

  currency: "INR";
};

type TicketTemplateHistoryEntry = {
  id: string;

  action: "saved" | "published" | "reset";

  settings: TicketTemplateSettings;

  createdAt: string;
};

const masterTicketStorageKeys = {
  settings: "buizz-master-ticket-template-settings",

  draft: "buizz-master-ticket-template-draft",

  history: "buizz-master-ticket-template-history",
} as const;

const masterTicketDefaultUpdatedAt = "2026-06-28T06:00:00.000Z";

