function createEntityPermissionState(
  storageKey: string,

  entityIds: string[],

  definitions: PermissionDefinition[],
): EntityPermissionState {
  const defaults = entityIds.reduce<EntityPermissionState>(
    (state, id) => ({
      ...state,
      [id]: createDefaultPermissionMap(definitions),
    }),

    {},
  );

  if (typeof window === "undefined") return defaults;

  try {
    const parsed = JSON.parse(
      window.localStorage.getItem(storageKey) ?? "{}",
    ) as EntityPermissionState;

    return mergeEntityPermissionsWithDefinitions(
      { ...defaults, ...parsed },

      entityIds,

      definitions,
    );
  } catch {
    return defaults;
  }
}

function persistEntityPermissionState(
  storageKey: string,
  state: EntityPermissionState,
) {
  if (typeof window === "undefined") return;

  window.localStorage.setItem(storageKey, JSON.stringify(state));

  dispatchPermissionsUpdated();
}

function readOrganizerEntityPermissionsForStore(
  storeId: string,
): Partial<OrganizerPermissions> {
  if (typeof window === "undefined") return {};

  const entityId =
    Object.entries(organizerPermissionStoreIdByEntityId).find(
      ([, mappedStoreId]) => mappedStoreId === storeId,
    )?.[0] ??
    readPermissionOrganizers().find(
      (organizer) => getPermissionOrganizerStoreId(organizer.id) === storeId,
    )?.id;

  if (!entityId) return {};

  try {
    const parsed = JSON.parse(
      window.localStorage.getItem("buizz-organizer-entity-permissions") ?? "{}",
    ) as EntityPermissionState;

    const entityPermissions = parsed[entityId];

    if (!entityPermissions || typeof entityPermissions !== "object") return {};

    return organizerPermissionDefinitions.reduce<Partial<OrganizerPermissions>>(
      (permissions, permission) => {
        const storeKey = getOrganizerStorePermissionKey(permission);

        if (
          !storeKey ||
          typeof entityPermissions[permission.id] !== "boolean"
        ) {
          return permissions;
        }

        return { ...permissions, [storeKey]: entityPermissions[permission.id] };
      },

      {},
    );
  } catch {
    return {};
  }
}

function createDefaultPermissionMap(definitions: PermissionDefinition[]) {
  return definitions.reduce<Record<string, boolean>>(
    (state, permission) => ({
      ...state,
      [permission.id]: permission.defaultEnabled,
    }),

    {},
  );
}

function toggleEntityPermission(
  current: EntityPermissionState,

  entityId: string,

  permissionId: string,

  definitions: PermissionDefinition[],
) {
  const existing = current[entityId] ?? createDefaultPermissionMap(definitions);

  return {
    ...current,

    [entityId]: { ...existing, [permissionId]: !existing[permissionId] },
  };
}

function removePermissionFromEntityState(
  current: EntityPermissionState,

  permissionId: string,
) {
  return Object.entries(current).reduce<EntityPermissionState>(
    (state, [entityId, permissions]) => {
      const nextPermissions = { ...permissions };

      delete nextPermissions[permissionId];

      return { ...state, [entityId]: nextPermissions };
    },

    {},
  );
}

function countActivePermissions(rolePermissions: Record<string, boolean>) {
  return Object.values(rolePermissions).filter(Boolean).length;
}

