type PlatformUserRole = "User" | "Organizer" | "Admin";

type PlatformUserStatus = "Active" | "Suspended";

type PlatformUserItem = {
  id: string;

  displayId: string;

  name: string;

  email: string;

  phone: string;

  city: string;

  role: PlatformUserRole;

  events: number;

  spent: string;

  joined: string;

  status: PlatformUserStatus;
};

function UsersView({ title }: { title: string }) {
  const { data: usersData, isLoading: usersLoading } = useGetAllUsersQuery({
    page: 1,
    limit: 100,
  });

  const [search, setSearch] = useState("");

  const [roleFilter, setRoleFilter] = useState<"All" | PlatformUserRole>("All");

  const [selectedUser, setSelectedUser] = useState<PlatformUserItem | null>(
    null,
  );

  // Transform API data to PlatformUserItem format
  const users = useMemo(() => {
    if (!usersData?.data?.users) return [];
    return usersData.data.users.map((apiUser) => ({
      id: String(
        apiUser.id ?? (apiUser as { user_id?: number | string }).user_id ?? "",
      ),
      displayId: String(
        apiUser.displayId ??
          (apiUser as { display_id?: number | string }).display_id ??
          apiUser.id ??
          (apiUser as { user_id?: number | string }).user_id ??
          "",
      ),
      name: apiUser.name,
      email: apiUser.email,
      phone: apiUser.phone || "N/A",
      city: "N/A", // API doesn't provide city
      role: apiUser.role as PlatformUserRole,
      events: 0, // API doesn't provide events count
      spent: "₹0", // API doesn't provide spent amount
      joined: new Date(
        apiUser.createdAt ??
          (apiUser as { created_at?: string }).created_at ??
          Date.now(),
      ).toLocaleDateString(),
      status:
        (apiUser.isActive ?? (apiUser as { is_active?: boolean }).is_active)
          ? "Active"
          : ("Suspended" as PlatformUserStatus),
    }));
  }, [usersData]);

  const filteredUsers = users.filter((user) => {
    const query = search.trim().toLowerCase();

    const matchesSearch =
      !query ||
      user.id.toLowerCase().includes(query) ||
      user.displayId.toLowerCase().includes(query) ||
      user.name.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query) ||
      user.phone.toLowerCase().includes(query) ||
      user.city.toLowerCase().includes(query) ||
      user.role.toLowerCase().includes(query);

    const matchesRole = roleFilter === "All" || user.role === roleFilter;

    return matchesSearch && matchesRole;
  });

  const activeUsers = users.filter((user) => user.status === "Active").length;

  const suspendedUsers = users.filter(
    (user) => user.status === "Suspended",
  ).length;

  const newThisMonthUsers = users.filter((user) =>
    /hour|day|week/i.test(user.joined),
  ).length;

  if (usersLoading) {
    return (
      <Panel title={title} description="Loading users...">
        <div className="flex items-center justify-center py-12">
          <div className="text-sm font-semibold text-[var(--app-muted)]">
            Loading users data...
          </div>
        </div>
      </Panel>
    );
  }

  const userStats = [
    {
      title: "Total Users",

      value: users.length.toLocaleString("en-IN"),

      icon: Users,

      tone: "brand" as const,
    },

    {
      title: "Active",

      value: activeUsers.toLocaleString("en-IN"),

      icon: CheckCircle2,

      tone: "success" as const,
    },

    {
      title: "Suspended",

      value: suspendedUsers.toLocaleString("en-IN"),

      icon: XCircle,

      tone: "danger" as const,
    },

    {
      title: "New This Month",

      value: newThisMonthUsers.toLocaleString("en-IN"),

      icon: Calendar,

      tone: "warning" as const,
    },
  ];

  const toggleUserStatus = (id: string) => {
    const nextStatus: PlatformUserStatus =
      users.find((user) => user.id === id)?.status === "Active"
        ? "Suspended"
        : "Active";

    setSelectedUser((current) =>
      current?.id === id
        ? {
            ...current,

            status: nextStatus,
          }
        : current,
    );
  };

  const downloadUserReport = (user?: PlatformUserItem) => {
    const reportUsers = user ? [user] : filteredUsers;

    const reportLines = [
      "Buizz Platform User Report",

      "",

      `Generated: ${new Date().toLocaleString("en-IN")}`,

      `Records: ${reportUsers.length}`,

      "",

      ...reportUsers.flatMap((item) => [
        `User ID: ${item.displayId}`,

        `Name: ${item.name}`,

        `Email: ${item.email}`,

        `Phone: ${item.phone}`,

        `City: ${item.city}`,

        `Role: ${item.role}`,

        `Bookings/Events: ${item.events}`,

        `Total Spent: ${item.spent}`,

        `Joined: ${item.joined}`,

        `Status: ${item.status}`,

        "",
      ]),
    ];

    const blob = new Blob([reportLines.join("\n")], {
      type: "text/plain;charset=utf-8",
    });

    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");

    link.href = url;

    link.download = user
      ? `${user.displayId.toLowerCase()}-user-report.txt`
      : "buizz-platform-users-report.txt";

    document.body.appendChild(link);

    link.click();

    link.remove();

    URL.revokeObjectURL(url);
  };

  const resetFilters = () => {
    setSearch("");

    setRoleFilter("All");
  };

  return (
    <section className="mx-auto grid w-full min-w-0 max-w-[1600px] gap-4 sm:gap-5">
      <section className="grid min-w-0 grid-cols-4 gap-1.5 sm:gap-3 xl:gap-4">
        {userStats.map((stat) => (
          <UserStatCard
            key={stat.title}
            title={stat.title}
            value={stat.value}
            icon={stat.icon}
            tone={stat.tone}
          />
        ))}
      </section>

      <section className="min-w-0 overflow-hidden rounded-[24px] border border-[var(--app-border)] bg-[var(--app-elevated)] shadow-[0_18px_54px_rgba(15,23,42,0.08)] sm:rounded-[2rem]">
        <div className="grid gap-4 border-b border-[var(--app-border)] p-4 sm:p-5 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-center">
          <div className="min-w-0">
            <p className="text-[10px] font-black uppercase tracking-[0.18em] text-[var(--color-brand-primary)] sm:text-[11px]">
              User Directory
            </p>

            <h2 className="mt-1 break-words text-2xl font-black leading-tight tracking-[-0.03em] text-[var(--app-foreground)]">
              Platform users
            </h2>

            <p className="mt-1 text-sm font-semibold leading-6 text-[var(--app-muted)]">
              Search customers, organizers, and admins from one responsive
              platform user view.
            </p>
          </div>

          <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-end">
            <span className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-[var(--app-border)] bg-[var(--app-subtle)] px-4 text-xs font-black text-[var(--app-muted)]">
              <Users className="size-4 text-[var(--color-brand-primary)]" />
              {filteredUsers.length} records
            </span>

            <button
              type="button"
              onClick={() => downloadUserReport()}
              className={dashboardSecondaryButtonClass}
            >
              <Download className="size-4" />
              Export Users
            </button>
          </div>
        </div>

        <div className="grid gap-3 border-b border-[var(--app-border)] p-3 sm:p-5 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-center">
          <div className="grid min-w-0 grid-cols-[minmax(0,1fr)_34px_42px_68px_48px] items-center gap-1.5 sm:grid-cols-[minmax(0,1fr)_48px_58px_92px_66px] sm:gap-2 lg:max-w-3xl">
            <div className="relative min-w-0">
              <Users className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-[var(--app-muted)] sm:left-4 sm:size-4" />

              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search users..."
                className="min-h-10 w-full min-w-0 rounded-full border border-[var(--app-border)] bg-[var(--app-subtle)] py-2 pl-9 pr-2 text-xs font-semibold text-[var(--app-foreground)] outline-none transition focus:border-[var(--color-brand-primary)] focus:bg-[var(--app-elevated)] focus:shadow-[0_0_0_4px_rgb(var(--brand-primary-rgb)/0.10)] placeholder:text-[var(--app-muted)] sm:min-h-11 sm:pl-11 sm:pr-4 sm:text-sm"
              />
            </div>

            {(["All", "User", "Organizer", "Admin"] as const).map((role) => (
              <button
                key={role}
                type="button"
                onClick={() => setRoleFilter(role)}
                className={`inline-flex min-h-9 min-w-0 items-center justify-center rounded-full px-1 text-[10px] font-black transition sm:min-h-10 sm:px-3 sm:text-xs ${
                  roleFilter === role
                    ? "bg-[var(--color-brand-primary)] text-white shadow-[0_12px_30px_rgb(var(--brand-primary-rgb)/0.22)]"
                    : "border border-[var(--app-border)] bg-[var(--app-elevated)] text-[var(--app-muted)] hover:border-[var(--color-brand-primary)] hover:text-[var(--color-brand-primary)]"
                }`}
              >
                {role}
              </button>
            ))}
          </div>

          <button
            type="button"
            onClick={resetFilters}
            className="inline-flex min-h-10 w-full items-center justify-center gap-2 rounded-full border border-[var(--app-border)] bg-[var(--app-elevated)] px-4 text-xs font-black text-[var(--app-foreground)] transition hover:border-[var(--color-brand-primary)] hover:text-[var(--color-brand-primary)] sm:w-auto"
          >
            <RefreshCw className="size-4" />
            Reset
          </button>
        </div>

        {filteredUsers.length ? (
          <div className="grid gap-3 p-3 lg:hidden">
            {filteredUsers.map((user) => (
              <article
                key={`mobile-user-${user.id}`}
                className="rounded-[24px] border border-[var(--app-border)] bg-[var(--app-subtle)] p-4 shadow-[0_12px_32px_rgba(15,23,42,0.05)]"
              >
                <div className="flex min-w-0 items-start justify-between gap-3">
                  <div className="flex min-w-0 items-start gap-3">
                    <span className="grid size-12 shrink-0 place-items-center rounded-2xl bg-[var(--color-brand-primary)]/10 text-base font-black text-[var(--color-brand-primary)]">
                      {user.name.charAt(0)}
                    </span>

                    <div className="min-w-0">
                      <p className="break-words text-lg font-black leading-tight text-[var(--app-foreground)]">
                        {user.name}
                      </p>

                      <p className="mt-1 break-all text-xs font-semibold leading-5 text-[var(--app-muted)]">
                        {user.email}
                      </p>
                    </div>
                  </div>

                  <UserStatusBadge status={user.status} />
                </div>

                <div className="mt-4 flex flex-wrap gap-2">
                  <UserRoleBadge role={user.role} />

                  <span className="inline-flex min-h-7 items-center rounded-full border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-[11px] font-black text-[var(--app-muted)]">
                    {user.displayId}
                  </span>
                </div>

                <div className="mt-4 grid grid-cols-2 gap-2">
                  <DetailBox label="Phone" value={user.phone} />

                  <DetailBox label="City" value={user.city} />

                  <DetailBox label="Bookings" value={String(user.events)} />

                  <DetailBox label="Spent" value={user.spent} />

                  <DetailBox label="Joined" value={user.joined} />

                  <DetailBox label="Role" value={user.role} />
                </div>

                <div className="mt-4 grid grid-cols-3 gap-2">
                  <button
                    type="button"
                    onClick={() => setSelectedUser(user)}
                    className={dashboardSecondaryButtonClass}
                  >
                    View
                  </button>

                  <button
                    type="button"
                    onClick={() => downloadUserReport(user)}
                    className={dashboardSecondaryButtonClass}
                  >
                    Report
                  </button>

                  <button
                    type="button"
                    onClick={() => toggleUserStatus(user.id)}
                    className={
                      user.status === "Active"
                        ? dashboardDangerButtonClass
                        : dashboardSuccessButtonClass
                    }
                  >
                    {user.status === "Active" ? "Suspend" : "Activate"}
                  </button>
                </div>
              </article>
            ))}
          </div>
        ) : (
          <div className="grid min-h-44 place-items-center p-6 text-center">
            <div>
              <Users className="mx-auto size-10 text-[var(--app-muted)]" />

              <p className="mt-3 text-lg font-black">No users found</p>

              <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
                Change your search or role filter.
              </p>
            </div>
          </div>
        )}

        {filteredUsers.length ? (
          <div className="hidden overflow-x-auto lg:block">
            <table className="w-full min-w-[1120px] text-left text-sm">
              <thead>
                <tr className="border-b border-[var(--app-border)] bg-[var(--app-subtle)] text-xs font-black uppercase tracking-[0.06em] text-[var(--app-muted)]">
                  <th className="px-4 py-4">User</th>

                  <th className="px-4 py-4">Contact</th>

                  <th className="px-4 py-4">City</th>

                  <th className="px-4 py-4">Role</th>

                  <th className="px-4 py-4">Bookings</th>

                  <th className="px-4 py-4">Spent</th>

                  <th className="px-4 py-4">Joined</th>

                  <th className="px-4 py-4">Status</th>

                  <th className="px-4 py-4">Actions</th>
                </tr>
              </thead>

              <tbody>
                {filteredUsers.map((user) => (
                  <tr
                    key={user.id}
                    className="border-b border-[var(--app-border)] align-top transition last:border-0 hover:bg-[var(--app-subtle)]/70"
                  >
                    <td className="px-4 py-4">
                      <div className="flex min-w-[220px] items-start gap-3">
                        <span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[var(--color-brand-primary)]/10 text-sm font-black text-[var(--color-brand-primary)]">
                          {user.name.charAt(0)}
                        </span>

                        <div className="min-w-0">
                          <p className="font-black leading-snug text-[var(--app-foreground)]">
                            {user.name}
                          </p>

                          <p className="mt-1 text-xs font-black text-[var(--color-brand-secondary)]">
                            {user.displayId}
                          </p>
                        </div>
                      </div>
                    </td>

                    <td className="px-4 py-4">
                      <p className="max-w-[220px] break-all font-semibold text-[var(--app-foreground)]">
                        {user.email}
                      </p>

                      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                        {user.phone}
                      </p>
                    </td>

                    <td className="px-4 py-4 font-semibold text-[var(--app-foreground)]">
                      {user.city}
                    </td>

                    <td className="px-4 py-4">
                      <UserRoleBadge role={user.role} />
                    </td>

                    <td className="px-4 py-4 font-black">{user.events}</td>

                    <td className="px-4 py-4 font-black">{user.spent}</td>

                    <td className="px-4 py-4 font-semibold text-[var(--app-muted)]">
                      {user.joined}
                    </td>

                    <td className="px-4 py-4">
                      <UserStatusBadge status={user.status} />
                    </td>

                    <td className="px-4 py-4">
                      <div className="grid min-w-[260px] grid-cols-3 gap-2">
                        <button
                          type="button"
                          onClick={() => setSelectedUser(user)}
                          className={dashboardSecondaryButtonClass}
                        >
                          View
                        </button>

                        <button
                          type="button"
                          onClick={() => downloadUserReport(user)}
                          className={dashboardSecondaryButtonClass}
                        >
                          Full Report
                        </button>

                        <button
                          type="button"
                          onClick={() => toggleUserStatus(user.id)}
                          className={
                            user.status === "Active"
                              ? dashboardDangerButtonClass
                              : dashboardSuccessButtonClass
                          }
                        >
                          {user.status === "Active" ? "Suspend" : "Activate"}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : null}
      </section>

      {selectedUser ? (
        <div className="fixed inset-0 z-50 grid items-end bg-black/60 p-0 backdrop-blur-sm sm:place-items-center sm:p-4">
          <div className="max-h-[92dvh] w-full max-w-3xl overflow-y-auto rounded-t-[28px] border border-[var(--app-border)] bg-[var(--app-elevated)] p-5 shadow-2xl sm:rounded-[28px]">
            <div className="mx-auto mb-4 h-1.5 w-12 rounded-full bg-[var(--app-border)] sm:hidden" />

            <div className="flex items-start justify-between gap-4">
              <div className="flex min-w-0 items-start gap-3">
                <span className="grid size-14 shrink-0 place-items-center rounded-2xl bg-[var(--color-brand-primary)]/10 text-xl font-black text-[var(--color-brand-primary)]">
                  {selectedUser.name.charAt(0)}
                </span>

                <div className="min-w-0">
                  <p className="text-[10px] font-black uppercase tracking-[0.18em] text-[var(--color-brand-primary)]">
                    User Profile
                  </p>

                  <h2 className="mt-1 break-words text-2xl font-black leading-tight">
                    {selectedUser.name}
                  </h2>

                  <p className="mt-1 break-all text-sm font-semibold text-[var(--app-muted)]">
                    {selectedUser.email}
                  </p>

                  <div className="mt-3 flex flex-wrap gap-2">
                    <UserRoleBadge role={selectedUser.role} />

                    <UserStatusBadge status={selectedUser.status} />
                  </div>
                </div>
              </div>

              <button
                type="button"
                onClick={() => setSelectedUser(null)}
                className="grid size-10 shrink-0 place-items-center rounded-xl border border-[var(--app-border)] bg-[var(--app-subtle)]"
                aria-label="Close user details modal"
              >
                <X className="size-4" />
              </button>
            </div>

            <div className="mt-5 grid gap-3 md:grid-cols-2">
              <DetailBox label="User ID" value={selectedUser.displayId} />

              <DetailBox label="Phone" value={selectedUser.phone} />

              <DetailBox label="City" value={selectedUser.city} />

              <DetailBox label="Role" value={selectedUser.role} />

              <DetailBox
                label="Bookings / Events"
                value={String(selectedUser.events)}
              />

              <DetailBox label="Total Spent" value={selectedUser.spent} />

              <DetailBox label="Joined" value={selectedUser.joined} />

              <DetailBox label="Status" value={selectedUser.status} />
            </div>

            <div className="mt-4 grid gap-3 md:grid-cols-3">
              <DetailBox
                label="Booking Summary"
                value={`${selectedUser.events} confirmed bookings`}
              />

              <DetailBox
                label="Payment Summary"
                value={`${selectedUser.spent} total paid`}
              />

              <DetailBox
                label="Moderation Summary"
                value={
                  selectedUser.status === "Suspended"
                    ? "Account is blocked from normal booking actions."
                    : "No active moderation block."
                }
              />
            </div>

            <div className="sticky bottom-0 -mx-5 mt-5 grid gap-2 border-t border-[var(--app-border)] bg-[var(--app-elevated)] px-5 py-4 sm:flex sm:flex-wrap sm:justify-end">
              <button
                type="button"
                onClick={() => downloadUserReport(selectedUser)}
                className={dashboardSecondaryButtonClass}
              >
                <Download className="size-4" />
                Download User Report
              </button>

              <button
                type="button"
                onClick={() => toggleUserStatus(selectedUser.id)}
                className={
                  selectedUser.status === "Active"
                    ? dashboardDangerButtonClass
                    : dashboardSuccessButtonClass
                }
              >
                {selectedUser.status === "Active"
                  ? "Suspend User"
                  : "Activate User"}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </section>
  );
}

function UserStatCard({
  title,

  value,

  icon: Icon = Users,

  tone = "brand",

  change,

  positive,
}: {
  title: string;

  value: string;

  icon?: LucideIcon;

  tone?: "brand" | "success" | "danger" | "warning";

  change?: string;

  positive?: boolean;
}) {
  const toneClass =
    tone === "success"
      ? "bg-[#22C55E]/10 text-[#16A34A] ring-[#22C55E]/20"
      : tone === "danger"
        ? "bg-[var(--color-brand-primary)]/10 text-[var(--color-brand-primary)] ring-[var(--color-brand-primary)]/20"
        : tone === "warning"
          ? "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)] ring-[var(--color-brand-accent)]/25"
          : "bg-[var(--color-brand-secondary)]/10 text-[var(--color-brand-secondary)] ring-[var(--color-brand-secondary)]/20";

  return (
    <article className="min-w-0 rounded-[16px] border border-[var(--app-border)] bg-[var(--app-elevated)] px-1.5 py-2 shadow-[0_10px_28px_rgba(15,23,42,0.06)] sm:rounded-[24px] sm:p-4 xl:p-5">
      <div className="flex min-w-0 items-center justify-between gap-1 sm:gap-2">
        <span
          className={`hidden shrink-0 place-items-center rounded-2xl ring-1 sm:grid sm:size-10 ${toneClass}`}
        >
          <Icon className="size-4" />
        </span>

        <span className="min-w-0 text-right text-base font-black leading-none text-[var(--app-foreground)] sm:ml-auto sm:text-3xl">
          {value}
        </span>
      </div>

      <p className="mt-2 min-w-0 text-[8.5px] font-black uppercase leading-tight tracking-[0.02em] text-[var(--app-muted)] sm:mt-3 sm:text-xs sm:tracking-[0.08em]">
        {title}
      </p>

      {change ? (
        <p
          className={`mt-1 hidden text-[10px] font-black sm:block ${positive ? "text-[#16A34A]" : "text-[var(--app-muted)]"}`}
        >
          {change}
        </p>
      ) : null}
    </article>
  );
}

function UserRoleBadge({ role }: { role: PlatformUserRole }) {
  const tone =
    role === "Admin"
      ? "bg-[var(--color-brand-secondary)]/15 text-[var(--color-brand-secondary)]"
      : role === "Organizer"
        ? "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)]"
        : "bg-[var(--app-muted)]/15 text-[var(--app-muted)]";

  return (
    <span className={`rounded-full px-3 py-1 text-[11px] font-black ${tone}`}>
      {role}
    </span>
  );
}

function UserStatusBadge({ status }: { status: PlatformUserStatus }) {
  const tone =
    status === "Active"
      ? "bg-[#22C55E]/15 text-[#22C55E]"
      : "bg-[var(--color-brand-primary)]/15 text-[var(--color-brand-primary)]";

  return (
    <span className={`rounded-full px-3 py-1 text-[11px] font-black ${tone}`}>
      {status}
    </span>
  );
}

