//                           onClick={() => updateEventStatus(event.id, "Rejected")}

//                           className="rounded-md bg-[var(--color-brand-primary)] px-3 py-2 text-xs font-black text-white"

//                         >

//                           Reject

//                         </button>

//                       </div>

//                     ) : (

//                       <span className="text-xs font-black text-[var(--app-muted)]">

//                         No action

