function OrganizerPaymentBadge({ status }: { status: OrganizerPaymentStatus }) {
  const tone =
    status === "Paid"
      ? "bg-[#22C55E]/15 text-[#22C55E]"
      : status === "Complimentary"
        ? "bg-[var(--color-brand-secondary)]/15 text-[var(--color-brand-secondary)]"
        : status === "Pending"
          ? "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)]"
          : status === "Refunded"
            ? "bg-[var(--color-brand-secondary)]/15 text-[var(--color-brand-secondary)]"
            : "bg-[var(--color-brand-primary)]/15 text-[var(--color-brand-primary)]";

  return (
    <span className={`rounded-full px-3 py-1 text-xs font-black ${tone}`}>
      {status}
    </span>
  );
}

function OrganizerBookingStatusBadge({
  status,
}: {
  status: OrganizerBookingStatus;
}) {
  const tone =
    status === "Confirmed" || status === "Checked In"
      ? "bg-[#22C55E]/15 text-[#22C55E]"
      : status === "Pending Payment" || status === "Refund Requested"
        ? "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)]"
        : status === "Refunded"
          ? "bg-[var(--color-brand-secondary)]/15 text-[var(--color-brand-secondary)]"
          : "bg-[var(--color-brand-primary)]/15 text-[var(--color-brand-primary)]";

  return (
    <span className={`rounded-full px-3 py-1 text-xs font-black ${tone}`}>
      {status}
    </span>
  );
}

