type VenueStatus = "Approved" | "Pending" | "Rejected";

type VenueItem = {
  id: string;

  name: string;

  city: string;

  capacity: string;

  organizer: string;

  eventsHosted: number;

  status: VenueStatus;

  hasSeatMap: boolean;
};

const venueData: VenueItem[] = [];

function VenuesView() {
  const [venues, setVenues] = useState<VenueItem[]>(venueData);
  const { data: venueEventsData, isLoading: venuesLoading } = useGetDraftEventsQuery();

  const [search, setSearch] = useState("");

  const [statusFilter, setStatusFilter] = useState<"All Status" | VenueStatus>(
    "All Status",
  );

  const [cityFilter, setCityFilter] = useState("All Cities");

  const [selectedVenue, setSelectedVenue] = useState<VenueItem | null>(null);

  useEffect(() => {
    const grouped = new Map<string, VenueItem>();
    (venueEventsData?.data?.events ?? []).forEach((event) => {
      const venueName = event.venue?.name?.trim();
      if (!venueName) return;
      const city = event.venue?.city?.trim() || "City pending";
      const key = `${venueName.toLowerCase()}|${city.toLowerCase()}`;
      const existing = grouped.get(key);
      const capacity = Number(event.totalSeats ?? 0);
      const approved = ["approved", "published", "ongoing", "completed"].includes(event.status);
      const rejected = event.status === "rejected" || event.status === "cancelled";
      grouped.set(key, {
        id: existing?.id ?? `VEN-${event.id}`,
        name: venueName,
        city,
        capacity: String(Math.max(Number(existing?.capacity ?? 0), capacity)),
        organizer: existing?.organizer || event.organizerName || event.organizationName || "Organizer unavailable",
        eventsHosted: (existing?.eventsHosted ?? 0) + 1,
        status: rejected ? "Rejected" : approved ? "Approved" : existing?.status ?? "Pending",
        hasSeatMap: existing?.hasSeatMap ?? false,
      });
    });
    setVenues(Array.from(grouped.values()));
  }, [venueEventsData]);

  const totalCapacity = venues.reduce(
    (sum, venue) => sum + Number(venue.capacity || 0),
    0,
  );

  const filteredVenues = venues.filter((venue) => {
    const query = search.toLowerCase();

    const matchesSearch =
      `${venue.name} ${venue.city} ${venue.organizer} ${venue.id}`
        .toLowerCase()
        .includes(query);

    const matchesStatus =
      statusFilter === "All Status" || venue.status === statusFilter;

    const matchesCity =
      cityFilter === "All Cities" || venue.city === cityFilter;

    return matchesSearch && matchesStatus && matchesCity;
  });

  const downloadVenueReport = (label: string) => {
    alert(`${label} will connect with backend API.`);
  };

  const updateVenueStatus = (id: string, status: VenueStatus) => {
    setVenues((current) =>
      current.map((venue) => (venue.id === id ? { ...venue, status } : venue)),
    );
  };

  return (
    <Panel
      title="Venue Management"
      description="Review and manage event venues across Maharashtra"
    >
      <div className="grid gap-5">
        <ResponsiveStatRow className="md:grid-cols-4">
          <ResponsiveStatCard
            title="Total Venues"
            value={venuesLoading ? "..." : String(venues.length)}
            detail="Unique venues from event records"
          />

          <ResponsiveStatCard
            title="Pending Approval"
            value={venuesLoading ? "..." : String(venues.filter((venue) => venue.status === "Pending").length)}
            detail="Awaiting an event decision"
          />

          <ResponsiveStatCard
            title="Approved Venues"
            value={venuesLoading ? "..." : String(venues.filter((venue) => venue.status === "Approved").length)}
            detail="Used by approved or published events"
          />

          <ResponsiveStatCard
            title="Total Capacity"
            value={venuesLoading ? "..." : totalCapacity.toLocaleString("en-IN")}
            detail="Capacity reported by event records"
          />
        </ResponsiveStatRow>

        <div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-subtle)]">
          <div className="flex flex-col gap-3 border-b border-[var(--app-border)] p-4 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h2 className="text-lg font-black">All Venues</h2>

              <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
                Manage venue approvals and status
              </p>
            </div>

            <div className="grid gap-2 sm:grid-cols-3 lg:flex lg:flex-wrap">
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search venue, city, organizer, ID..."
                className="min-h-10 min-w-0 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-sm font-semibold outline-none"
              />

              <select
                value={cityFilter}
                onChange={(event) => setCityFilter(event.target.value)}
                className="min-h-10 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-sm font-black outline-none"
              >
                <option>All Cities</option>

                {[...new Set(venues.map((venue) => venue.city))].map(
                  (city) => (
                    <option key={city}>{city}</option>
                  ),
                )}
              </select>

              <select
                value={statusFilter}
                onChange={(event) =>
                  setStatusFilter(
                    event.target.value as "All Status" | VenueStatus,
                  )
                }
                className="min-h-10 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-sm font-black outline-none"
              >
                <option>All Status</option>

                <option>Approved</option>

                <option>Pending</option>

                <option>Rejected</option>
              </select>
            </div>
          </div>

          <div className="grid gap-3 p-4 lg:hidden">
            {filteredVenues.map((venue) => (
              <article
                key={`mobile-${venue.id}`}
                className={dashboardCardClass}
              >
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div className="min-w-0">
                    <h3 className="break-words text-lg font-black">
                      {venue.name}
                    </h3>

                    <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                      {venue.id} - {venue.city}
                    </p>
                  </div>

                  <VenueStatusBadge status={venue.status} />
                </div>

                <div className="mt-4 grid gap-3 sm:grid-cols-2">
                  <DetailBox label="Capacity" value={venue.capacity} />

                  <DetailBox label="Organizer" value={venue.organizer} />

                  <DetailBox
                    label="Events Hosted"
                    value={String(venue.eventsHosted)}
                  />

                  <DetailBox
                    label="Seat Map Status"
                    value={
                      venue.hasSeatMap
                        ? "Base layout available"
                        : "No base layout assigned"
                    }
                  />
                </div>

                <ResponsiveActionGroup>
                  <button
                    type="button"
                    onClick={() => setSelectedVenue(venue)}
                    className={dashboardSecondaryButtonClass}
                  >
                    View Venue Details
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      downloadVenueReport(
                        `Download venue report for ${venue.name}`,
                      )
                    }
                    className={dashboardSecondaryButtonClass}
                  >
                    Venue Report
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      alert(
                        venue.hasSeatMap
                          ? `${venue.name} base seat map preview will open here.`
                          : `${venue.name} base seat map builder will open here.`,
                      )
                    }
                    className={dashboardSecondaryButtonClass}
                  >
                    {venue.hasSeatMap
                      ? "View Seat Map"
                      : "Create Seat Map / Assign Layout"}
                  </button>

                  {venue.status === "Pending" ? (
                    <>
                      <button
                        type="button"
                        onClick={() => updateVenueStatus(venue.id, "Approved")}
                        className={dashboardSuccessButtonClass}
                      >
                        Approve
                      </button>

                      <button
                        type="button"
                        onClick={() => updateVenueStatus(venue.id, "Rejected")}
                        className={dashboardDangerButtonClass}
                      >
                        Reject
                      </button>
                    </>
                  ) : null}
                </ResponsiveActionGroup>
              </article>
            ))}
          </div>

          <div className="hidden overflow-x-auto lg:block">
            <table className="w-full min-w-[900px] text-left text-sm">
              <thead>
                <tr className="border-b border-[var(--app-border)] text-xs font-black uppercase text-[var(--app-muted)]">
                  <th className="px-4 py-4">Venue Name</th>

                  <th className="px-4 py-4">City</th>

                  <th className="px-4 py-4">Capacity</th>

                  <th className="px-4 py-4">Organizer</th>

                  <th className="px-4 py-4">Events Hosted</th>

                  <th className="px-4 py-4">Status</th>

                  <th className="px-4 py-4">Actions</th>
                </tr>
              </thead>

              <tbody>
                {filteredVenues.map((venue) => (
                  <tr
                    key={venue.id}
                    className="border-b border-[var(--app-border)] last:border-0"
                  >
                    <td className="px-4 py-4">
                      <p className="font-black">{venue.name}</p>

                      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                        {venue.id}
                      </p>
                    </td>

                    <td className="px-4 py-4 font-semibold">{venue.city}</td>

                    <td className="px-4 py-4 font-black">{venue.capacity}</td>

                    <td className="px-4 py-4 font-semibold">
                      {venue.organizer}
                    </td>

                    <td className="px-4 py-4 font-semibold">
                      {venue.eventsHosted}
                    </td>

                    <td className="px-4 py-4">
                      <VenueStatusBadge status={venue.status} />
                    </td>

                    <td className="px-4 py-4">
                      <div className="flex flex-wrap gap-2">
                        <button
                          type="button"
                          onClick={() => setSelectedVenue(venue)}
                          className="rounded-md border border-[var(--app-border)] px-3 py-2 text-xs font-black"
                        >
                          View Venue Details
                        </button>

                        <button
                          type="button"
                          onClick={() =>
                            downloadVenueReport(
                              `Download venue report for ${venue.name}`,
                            )
                          }
                          className="rounded-md border border-[var(--color-brand-secondary)]/30 bg-[var(--color-brand-secondary)]/10 px-3 py-2 text-xs font-black text-[var(--color-brand-secondary)]"
                        >
                          Venue Report
                        </button>

                        {venue.hasSeatMap ? (
                          <button
                            type="button"
                            onClick={() =>
                              alert(
                                `${venue.name} base seat map preview will open here.`,
                              )
                            }
                            className="rounded-md border border-[var(--app-border)] px-3 py-2 text-xs font-black"
                          >
                            View Seat Map
                          </button>
                        ) : (
                          <button
                            type="button"
                            onClick={() =>
                              alert(
                                `${venue.name} base seat map builder will open here.`,
                              )
                            }
                            className="rounded-md border border-[var(--app-border)] px-3 py-2 text-xs font-black"
                          >
                            Create Seat Map / Assign Layout
                          </button>
                        )}

                        {venue.status === "Pending" ? (
                          <>
                            <button
                              type="button"
                              onClick={() =>
                                updateVenueStatus(venue.id, "Approved")
                              }
                              className="rounded-md bg-[#22C55E] px-3 py-2 text-xs font-black text-white"
                            >
                              Approve
                            </button>

                            <button
                              type="button"
                              onClick={() =>
                                updateVenueStatus(venue.id, "Rejected")
                              }
                              className="rounded-md bg-[var(--color-brand-primary)] px-3 py-2 text-xs font-black text-white"
                            >
                              Reject
                            </button>
                          </>
                        ) : null}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {selectedVenue ? (
        <VenueDetailsModal
          venue={selectedVenue}
          onClose={() => setSelectedVenue(null)}
          onDownload={downloadVenueReport}
        />
      ) : null}
    </Panel>
  );
}

