function VenueStatusBadge({ status }: { status: VenueStatus }) {
  const tone =
    status === "Approved"
      ? "bg-[#22C55E]/15 text-[#22C55E]"
      : status === "Pending"
        ? "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)]"
        : "bg-[var(--color-brand-primary)]/15 text-[var(--color-brand-primary)]";

  return (
    <span className={`rounded-full px-3 py-1 text-[11px] font-black ${tone}`}>
      {status}
    </span>
  );
}

