function matchesReportFilters({
  city,
  organizer,
  status,
  search,
  targetCity,
  targetOrganizer,
  targetStatus,
  text,
}: {
  city: string;
  organizer: string;
  status: string;
  search: string;
  targetCity: string;
  targetOrganizer: string;
  targetStatus: string;
  text: string;
}) {
  return (
    (city === "All Cities" ||
      targetCity === city ||
      targetCity === "All Cities") &&
    (organizer === "All Organizers" ||
      targetOrganizer === organizer ||
      targetOrganizer === "All Organizers") &&
    (status === "All Status" || targetStatus === status) &&
    text.toLowerCase().includes(search.toLowerCase())
  );
}

type LegacySupportTicketStatus = "Open" | "In Progress" | "Resolved";

type LegacySupportTicketPriority = "High" | "Medium" | "Low";

type SupportTicketItem = {
  id: string;

  subject: string;

  organizer: string;

  email: string;

  category: string;

  priority: LegacySupportTicketPriority;

  status: LegacySupportTicketStatus;

  createdAt: string;

  assignedTo: string;
};

const supportTicketsData: SupportTicketItem[] = [];

function SupportView() {
  const [tickets, setTickets] =
    useState<SupportTicketItem[]>(supportTicketsData);

  const [search, setSearch] = useState("");

  const [statusFilter, setStatusFilter] = useState<
    "All Status" | LegacySupportTicketStatus
  >("All Status");

  const [selectedTicket, setSelectedTicket] =
    useState<SupportTicketItem | null>(null);

  const filteredTickets = tickets.filter((ticket) => {
    const query = search.toLowerCase();

    const matchesSearch =
      ticket.subject.toLowerCase().includes(query) ||
      ticket.organizer.toLowerCase().includes(query) ||
      ticket.email.toLowerCase().includes(query) ||
      ticket.id.toLowerCase().includes(query);

    const matchesStatus =
      statusFilter === "All Status" || ticket.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const updateTicketStatus = (
    id: string,
    status: LegacySupportTicketStatus,
  ) => {
    setTickets((current) => {
      const updated = current.map((ticket) =>
        ticket.id === id
          ? {
              ...ticket,

              status,

              assignedTo:
                status === "In Progress" && ticket.assignedTo === "Unassigned"
                  ? "Support Admin"
                  : ticket.assignedTo,
            }
          : ticket,
      );

      const latestSelected = updated.find((ticket) => ticket.id === id) ?? null;

      setSelectedTicket(latestSelected);

      return updated;
    });
  };

  return (
    <Panel
      title="Support"
      description="Organizer support tickets and response-time snapshot."
    >
      <div className="grid gap-5">
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <UserStatCard
            title="Open Tickets"
            value={String(
              tickets.filter((ticket) => ticket.status === "Open").length,
            )}
            change="Waiting on Buizz"
            positive
          />

          <UserStatCard
            title="In Progress"
            value={String(
              tickets.filter((ticket) => ticket.status === "In Progress")
                .length,
            )}
            change="Assigned"
            positive
          />

          <UserStatCard
            title="Resolved"
            value="24"
            change="This month"
            positive
          />

          <UserStatCard
            title="Avg. Response"
            value="2h 15m"
            change="Support SLA"
            positive
          />
        </div>

        <div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-subtle)]">
          <div className="flex flex-col gap-3 border-b border-[var(--app-border)] p-4 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h2 className="text-lg font-black">Support Tickets</h2>

              <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
                Track organizer issues, assignments, priorities, and resolution
                status.
              </p>
            </div>

            <div className="flex flex-wrap gap-2">
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search ticket, organizer, email..."
                className="min-h-10 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-sm font-semibold outline-none"
              />

              <select
                value={statusFilter}
                onChange={(event) =>
                  setStatusFilter(
                    event.target.value as
                      | "All Status"
                      | LegacySupportTicketStatus,
                  )
                }
                className="min-h-10 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-sm font-black outline-none"
              >
                <option>All Status</option>

                <option>Open</option>

                <option>In Progress</option>

                <option>Resolved</option>
              </select>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full min-w-[1050px] text-left text-sm">
              <thead>
                <tr className="border-b border-[var(--app-border)] text-xs font-black uppercase text-[var(--app-muted)]">
                  <th className="px-4 py-4">Ticket</th>

                  <th className="px-4 py-4">Organizer</th>

                  <th className="px-4 py-4">Category</th>

                  <th className="px-4 py-4">Priority</th>

                  <th className="px-4 py-4">Status</th>

                  <th className="px-4 py-4">Assigned To</th>

                  <th className="px-4 py-4">Created</th>

                  <th className="px-4 py-4">Actions</th>
                </tr>
              </thead>

              <tbody>
                {filteredTickets.map((ticket) => (
                  <tr
                    key={ticket.id}
                    className="border-b border-[var(--app-border)] last:border-0"
                  >
                    <td className="px-4 py-4">
                      <p className="font-black">{ticket.subject}</p>

                      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                        {ticket.id}
                      </p>
                    </td>

                    <td className="px-4 py-4">
                      <p className="font-black">{ticket.organizer}</p>

                      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
                        {ticket.email}
                      </p>
                    </td>

                    <td className="px-4 py-4 font-semibold">
                      {ticket.category}
                    </td>

                    <td className="px-4 py-4">
                      <SupportPriorityBadge priority={ticket.priority} />
                    </td>

                    <td className="px-4 py-4">
                      <StatusPill label={ticket.status} />
                    </td>

                    <td className="px-4 py-4 font-semibold">
                      {ticket.assignedTo}
                    </td>

                    <td className="px-4 py-4 font-semibold">
                      {ticket.createdAt}
                    </td>

                    <td className="px-4 py-4">
                      <div className="flex flex-wrap gap-2">
                        <button
                          type="button"
                          onClick={() => setSelectedTicket(ticket)}
                          className="rounded-md border border-[var(--app-border)] px-3 py-2 text-xs font-black"
                        >
                          View
                        </button>

                        {ticket.status !== "Resolved" ? (
                          <button
                            type="button"
                            onClick={() =>
                              updateTicketStatus(ticket.id, "Resolved")
                            }
                            className="rounded-md bg-[#22C55E] px-3 py-2 text-xs font-black text-white"
                          >
                            Resolve
                          </button>
                        ) : null}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {selectedTicket ? (
        <div className="fixed inset-0 z-50 grid items-end bg-black/60 p-0 backdrop-blur-sm sm:place-items-center sm:p-4">
          <div className="w-full max-w-2xl rounded-2xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-5 shadow-2xl">
            <div className="flex items-start justify-between gap-4">
              <div>
                <p className="text-xs font-black uppercase text-[var(--color-brand-primary)]">
                  Support Ticket
                </p>

                <h2 className="mt-1 text-xl font-black">
                  {selectedTicket.subject}
                </h2>

                <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
                  {selectedTicket.id} • {selectedTicket.createdAt}
                </p>
              </div>

              <button
                type="button"
                onClick={() => setSelectedTicket(null)}
                className="rounded-md border border-[var(--app-border)] px-3 py-2 text-xs font-black"
              >
                Close
              </button>
            </div>

            <div className="mt-5 grid gap-3 md:grid-cols-2">
              <DetailBox label="Organizer" value={selectedTicket.organizer} />

              <DetailBox label="Email" value={selectedTicket.email} />

              <DetailBox label="Category" value={selectedTicket.category} />

              <DetailBox label="Priority" value={selectedTicket.priority} />

              <DetailBox label="Status" value={selectedTicket.status} />

              <DetailBox
                label="Assigned To"
                value={selectedTicket.assignedTo}
              />
            </div>

            <div className="mt-4 rounded-xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-4">
              <p className="text-xs font-black uppercase text-[var(--app-muted)]">
                Conversation / Notes
              </p>

              <p className="mt-2 text-sm font-semibold leading-6">
                Organizer reported this issue from dashboard. Super Admin can
                assign this to support/admin team later when backend ticket API
                is connected.
              </p>
            </div>

            <div className="mt-5 flex flex-wrap justify-end gap-2">
              <button
                type="button"
                onClick={() =>
                  updateTicketStatus(selectedTicket.id, "In Progress")
                }
                className="min-h-10 rounded-md border border-[var(--app-border)] px-4 text-xs font-black"
              >
                Mark In Progress
              </button>

              <button
                type="button"
                onClick={() =>
                  updateTicketStatus(selectedTicket.id, "Resolved")
                }
                className="min-h-10 rounded-md bg-[#22C55E] px-4 text-xs font-black text-white"
              >
                Mark Resolved
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </Panel>
  );
}

function SupportPriorityBadge({
  priority,
}: {
  priority: SupportTicketPriority;
}) {
  return (
    <span
      className={`rounded-full px-3 py-1 text-[11px] font-black ${getPriorityTone(priority)}`}
    >
      {priority}
    </span>
  );
}

const supportInputClass =
  "min-h-10 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 text-sm font-semibold outline-none focus:border-[var(--color-brand-primary)]";

function getPriorityTone(priority: SupportTicketPriority | NotificationPriority | "urgent") {
  const normalized = String(priority).toLowerCase();

  if (normalized === "urgent" || normalized === "critical") return "bg-[#581c87]/15 text-[#581c87]";

  if (normalized === "high")
    return "bg-[var(--color-brand-primary)]/15 text-[var(--color-brand-primary)]";

  if (normalized === "medium")
    return "bg-[var(--color-brand-accent)]/15 text-[var(--color-brand-accent)]";

  return "bg-[#22C55E]/15 text-[#22C55E]";
}

type SupportStatusFilter = "All Status" | SupportTicketStatus;

type SupportSourceFilter = "All Sources" | SupportTicket["sourceType"];

type SupportCategoryFilter = "All Categories" | SupportTicketCategory;

type SupportPriorityFilter = "All Priorities" | SupportTicketPriority;

type SupportAssigneeFilter = "All Assignees" | SupportTicketAssignee;

function OrganizerSupportView() {
  const storedPermissions = usePermissionStore(
    (state) => state.organizerPermissions["org-festlane"],
  );

  const permissions = {
    ...defaultOrganizerPermissions,
    ...(storedPermissions ?? {}),
  };

  const [tickets, setTickets] = useState<SupportTicket[]>(() =>
    getSupportTickets(),
  );

  const [search, setSearch] = useState("");

  const [statusFilter, setStatusFilter] =
    useState<SupportStatusFilter>("All Status");

  const [message, setMessage] = useState("");

  const [form, setForm] = useState({
    category: "Technical Issue" as SupportTicketCategory,

    subject: "",

    description: "",

    relatedEvent: "",
  });

  const organizerName = "FestLane Studios";

  const organizerEmail = "ayaan@festlane.local";

  const ownTickets = tickets.filter(
    (ticket) =>
      ticket.sourceType === "Organizer" &&
      ticket.requesterEmail === organizerEmail,
  );

  const filteredTickets = ownTickets.filter((ticket) => {
    const query = search.toLowerCase();

    return (
      `${ticket.id} ${ticket.subject} ${ticket.category} ${ticket.description}`
        .toLowerCase()
        .includes(query) &&
      (statusFilter === "All Status" || ticket.status === statusFilter)
    );
  });

  const submitTicket = () => {
    if (!form.subject.trim() || !form.description.trim()) {
      setMessage("Subject and description are required.");

      return;
    }

    const now = getSupportTimestamp();

    const ticket: SupportTicket = {
      id: createSupportTicketId(),

      sourceType: "Organizer",

      requesterName: organizerName,

      requesterEmail: organizerEmail,

      subject: form.subject.trim(),

      description: form.relatedEvent.trim()
        ? `${form.description.trim()}\n\nRelated event: ${form.relatedEvent.trim()}`
        : form.description.trim(),

      category: form.category,

      priority: getAutoSupportPriority(form.category),

      status: "Open",

      assignedTo: "Unassigned",

      createdAt: now,

      lastUpdated: now,
    };

    setTickets((current) => {
      const updated = [ticket, ...current];

      saveSupportTickets(updated);

      return updated;
    });

    setForm({
      category: "Technical Issue",
      subject: "",
      description: "",
      relatedEvent: "",
    });

    setMessage("Support ticket submitted.");
  };

  return (
    <Panel
      title="Support"
      description="Create organizer support tickets and track only your own requests."
    >
      <div className="grid gap-5 lg:grid-cols-[420px_minmax(0,1fr)]">
        <div className="rounded-2xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-4">
          <h2 className="text-lg font-black">Create Support Ticket</h2>

          <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
            Raise event, scanner, settlement, or technical issues for Buizz
            support.
          </p>

          {permissions.createSupportTicket ? (
            <div className="mt-4 grid gap-3">
              <label className="grid gap-1 text-xs font-black uppercase text-[var(--app-muted)]">
                Category
                <select
                  value={form.category}
                  onChange={(event) =>
                    setForm((current) => ({
                      ...current,
                      category: event.target.value as SupportTicketCategory,
                    }))
                  }
                  className={supportInputClass}
                >
                  {supportTicketCategories.map((category) => (
                    <option key={category}>{category}</option>
                  ))}
                </select>
              </label>

              <label className="grid gap-1 text-xs font-black uppercase text-[var(--app-muted)]">
                Subject
                <input
                  value={form.subject}
                  onChange={(event) =>
                    setForm((current) => ({
                      ...current,
                      subject: event.target.value,
                    }))
                  }
                  className={supportInputClass}
                />
              </label>

              <label className="grid gap-1 text-xs font-black uppercase text-[var(--app-muted)]">
                Description
                <textarea
                  value={form.description}
                  onChange={(event) =>
                    setForm((current) => ({
                      ...current,
                      description: event.target.value,
                    }))
                  }
                  className="min-h-28 rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 py-2 text-sm font-semibold outline-none focus:border-[var(--color-brand-primary)]"
                />
              </label>

              <div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-elevated)] p-3 text-xs font-black text-[var(--app-muted)]">
                Estimated priority:{" "}
                <span className="text-[var(--app-foreground)]">
                  {getAutoSupportPriority(form.category)}
                </span>
                <p className="mt-1 font-semibold">
                  Final priority can be adjusted by Buizz Super Admin.
                </p>
              </div>

              <label className="grid gap-1 text-xs font-black uppercase text-[var(--app-muted)]">
                Related Event Optional
                <input
                  value={form.relatedEvent}
                  onChange={(event) =>
                    setForm((current) => ({
                      ...current,
                      relatedEvent: event.target.value,
                    }))
                  }
                  className={supportInputClass}
                />
              </label>

              {message ? (
                <p className="rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] px-3 py-2 text-xs font-black text-[var(--app-muted)]">
                  {message}
                </p>
              ) : null}

              <button
                type="button"
                onClick={submitTicket}
                className="min-h-11 rounded-md bg-[var(--color-brand-primary)] px-4 text-sm font-black text-white"
              >
                Submit Ticket
              </button>
            </div>
          ) : (
            <div className="mt-4 rounded-xl border border-[var(--color-brand-primary)]/30 bg-[var(--color-brand-primary)]/10 p-4 text-sm font-black text-[var(--color-brand-primary)]">
              Create Support Ticket permission is disabled.
            </div>
          )}
        </div>

        <div className="min-w-0 rounded-2xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-4">
          <div className="flex flex-col gap-3 border-b border-[var(--app-border)] pb-4 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h2 className="text-lg font-black">My Support Tickets</h2>

              <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
                Status and assigned team for your organization.
              </p>
            </div>

            <div className="flex flex-col gap-2 sm:flex-row">
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search own tickets..."
                className={supportInputClass}
              />

              <select
                value={statusFilter}
                onChange={(event) =>
                  setStatusFilter(event.target.value as SupportStatusFilter)
                }
                className={supportInputClass}
              >
                <option>All Status</option>

                {supportTicketStatuses.map((status) => (
                  <option key={status}>{status}</option>
                ))}
              </select>
            </div>
          </div>

          {permissions.viewOwnSupportTickets ? (
            <SupportTicketsTable
              tickets={filteredTickets}
              onView={() => undefined}
              actions={() => (
                <span className="text-xs font-black text-[var(--app-muted)]">
                  Reply placeholder
                </span>
              )}
              compact
            />
          ) : (
            <div className="mt-4 rounded-xl border border-[var(--color-brand-primary)]/30 bg-[var(--color-brand-primary)]/10 p-4 text-sm font-black text-[var(--color-brand-primary)]">
              View Own Support Tickets permission is disabled.
            </div>
          )}
        </div>
      </div>
    </Panel>
  );
}

