function SupportActionButton({
  label,
  onClick,
  tone = "neutral",
}: {
  label: string;
  onClick: () => void;
  tone?: "neutral" | "success" | "danger";
}) {
  const toneClass =
    tone === "success"
      ? "border-[#22C55E]/30 bg-[#22C55E] text-white"
      : tone === "danger"
        ? "border-[var(--app-foreground)] bg-[var(--app-foreground)] text-white"
        : "border-[var(--app-border)] bg-[var(--app-elevated)]";

  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-md border px-3 py-2 text-xs font-black ${toneClass}`}
    >
      {label}
    </button>
  );
}

