function LockedApprovalRule({
  title,

  description,
}: {
  title: string;

  description: string;
}) {
  return (
    <div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-4">
      <p className="text-sm font-black">{title}</p>

      <p className="mt-1 text-xs font-semibold text-[var(--app-muted)]">
        {description}
      </p>

      <div className="mt-3 rounded-lg bg-[var(--color-brand-accent)]/10 px-3 py-2 text-xs font-bold text-[var(--color-brand-accent)]">
        Locked until Admin / Super Admin approval.
      </div>
    </div>
  );
}

function SettingsCard({
  title,

  description,

  icon: Icon,

  children,
}: {
  title: string;

  description: string;

  icon: LucideIcon;

  children: ReactNode;
}) {
  return (
    <section className="rounded-2xl border border-[var(--app-border)] bg-[var(--app-subtle)] p-5">
      <div className="mb-5 flex items-start gap-3">
        <span className="grid size-11 place-items-center rounded-xl bg-[var(--color-brand-primary)]/10 text-[var(--color-brand-primary)]">
          <Icon className="size-5" />
        </span>

        <div>
          <h2 className="text-lg font-black">{title}</h2>

          <p className="mt-1 text-sm font-semibold text-[var(--app-muted)]">
            {description}
          </p>
        </div>
      </div>

      {children}
    </section>
  );
}

function OrganizerApprovalGate({ status }: { status: string }) {
  const config = getOrganizerStatusConfig(status);

  return (
    <main className="grid min-h-screen place-items-center bg-[var(--app-background)] px-4 text-center text-[var(--app-foreground)]">
      <section className="max-w-lg rounded-md border border-[var(--app-border)] bg-[var(--app-elevated)] p-6 shadow-[0_18px_58px_rgba(0,0,0,0.12)]">
        <config.icon className={`mx-auto size-12 ${config.color}`} />

        <h1 className="mt-4 text-3xl font-black">
          Organizer approval required
        </h1>

        <p className="mt-2 text-sm font-semibold text-[var(--app-muted)]">
          {config.message}
        </p>

        <Link
          href="/organizer/application-status"
          className="mt-5 inline-flex min-h-11 items-center rounded-md bg-[var(--color-brand-primary)] px-5 text-sm font-black text-white"
        >
          View Application Status
        </Link>
      </section>
    </main>
  );
}

function getOrganizerStatusConfig(status: string) {
  if (status === "approved")
    return {
      label: "Approved",
      message:
        "Your organizer account is approved. Dashboard access is now available.",
      icon: CheckCircle2,
      color: "text-[#22C55E]",
      bg: "bg-[#22C55E]/10",
    };

  if (status === "rejected")
    return {
      label: "Rejected",
      message:
        "Your organizer application needs changes before dashboard access.",
      icon: XCircle,
      color: "text-[var(--color-brand-primary)]",
      bg: "bg-[var(--color-brand-primary)]/10",
    };

  if (status === "pending-super-admin")
    return {
      label: "Pending Super Admin Review",
      message: "Admin approved your application. Final review is pending.",
      icon: Clock,
      color: "text-[var(--color-brand-secondary)]",
      bg: "bg-[var(--color-brand-secondary)]/10",
    };

  return {
    label: "Pending Admin Review",
    message:
      "Your application is under review. Dashboard remains locked until approval.",
    icon: Clock,
    color: "text-[var(--color-brand-accent)]",
    bg: "bg-[var(--color-brand-accent)]/10",
  };
}
